INSERT INTO exam_questions (subject, grade, question_type, question_text, options, answer, explanation, difficulty, topic)
VALUES
  ('ต้านทุจริต', 'ป.4', 'mcq', 'สิ่งของในข้อใดจัดเป็น "ของใช้ส่วนรวม" ภายในโรงเรียน', '["ไม้กวาดห้องเรียน","แปรงสีฟันประจำตัว","แก้วน้ำประจำตัว","กระเป๋านักเรียน"]'::jsonb, '0'::jsonb, 'ไม้กวาดห้องเรียนเป็นของใช้ส่วนรวมที่ทุกคนในห้องเรียนใช้ร่วมกันในการทำความสะอาด ต่างจากแปรงสีฟัน แก้วน้ำ และกระเป๋าที่เป็นของใช้ส่วนตัว', 'easy', '[หน่วยที่ 1] ของใช้ส่วนตนและของใช้ส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็น "ของใช้ส่วนตัว" ที่ไม่ควรนำไปใช้ร่วมกับผู้อื่นเพื่อสุขอนามัย', '["โต๊ะเรียน","ผ้าเช็ดหน้า","พัดลมเพดาน","ถังขยะ"]'::jsonb, '1'::jsonb, 'ผ้าเช็ดหน้าเป็นของใช้ส่วนตัวที่สัมผัสร่างกายโดยตรง ไม่ควรใช้ร่วมกับผู้อื่นเพื่อสุขอนามัยและป้องกันโรคติดต่อ', 'easy', '[หน่วยที่ 1] ของใช้ส่วนตนและของใช้ส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อนักเรียนใช้ลูกฟุตบอลของโรงเรียนเล่นเสร็จแล้ว ควรปฏิบัติอย่างไร', '["ทิ้งไว้กลางสนามให้ภารโรงเก็บ","เตะเข้าไปไว้ใต้บันไดอาคาร","นำไปเก็บเข้าตู้เก็บอุปกรณ์กีฬาให้เรียบร้อย","นำกลับไปเล่นต่อที่บ้าน"]'::jsonb, '2'::jsonb, 'ของใช้ส่วนรวมเมื่อใช้เสร็จแล้วต้องนำไปเก็บคืนที่เดิมให้เรียบร้อย เพื่อให้เพื่อนคนอื่นสามารถนำไปใช้งานต่อได้', 'easy', '[หน่วยที่ 1] การใช้ประโยชน์จากทรัพย์สินส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การกระทำใดถือเป็นการนำ "ทรัพย์สินส่วนรวม" ไปใช้เป็นประโยชน์ส่วนตัว', '["ยืมหนังสือห้องสมุดตามระเบียบ","นั่งพักผ่อนใต้ร่มไม้ในโรงเรียน","ดื่มน้ำจากก๊อกน้ำดื่มของโรงเรียน","นำกระดาษรายงานของโรงเรียนกลับไปพับจรวดเล่นที่บ้าน"]'::jsonb, '3'::jsonb, 'การนำกระดาษรายงานของโรงเรียนซึ่งเป็นของส่วนรวมกลับไปเล่นส่วนตัวที่บ้าน เป็นการเบียดเบียนทรัพย์สินส่วนรวม', 'easy', '[หน่วยที่ 1] การไม่นำของส่วนรวมไปใช้ประโยชน์ส่วนตน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การ "เข้าแถวซื้ออาหาร" ในโรงอาหารแสดงถึงสิ่งใด', '["การเคารพสิทธิส่วนรวมและความเป็นระเบียบ","ความกลัวว่าจะไม่ได้อาหาร","การเสียเวลาโดยไม่จำเป็น","การเอาใจใส่เฉพาะเพื่อนสนิท"]'::jsonb, '0'::jsonb, 'การเข้าแถวตามลำดับก่อน-หลัง เป็นการเคารพสิทธิของทุกคนในสังคมและรักษาระเบียบวินัยส่วนรวม', 'easy', '[หน่วยที่ 1] การคิดแยกแยะผลประโยชน์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นการใช้ "น้ำประปาของโรงเรียน" อย่างถูกต้องและคุ้มค่า', '["เปิดน้ำทิ้งไว้ระหว่างแปรงฟัน","ปิดก๊อกน้ำให้สนิททุกครั้งหลังใช้งานเสร็จ","เปิดก๊อกน้ำแรงสุดเพื่อสาดเล่นกับเพื่อน","ใช้สายยางฉีดล้างรองเท้าเปื้อนโคลนเล่น"]'::jsonb, '1'::jsonb, 'การปิดก๊อกน้ำให้สนิทหลังใช้งานช่วยประหยัดทรัพยากรส่วนรวมและลดค่าน้ำของโรงเรียน', 'easy', '[หน่วยที่ 1] การใช้ประโยชน์จากทรัพย์สินส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ถ้าเพื่อนขอยืมดินสอส่วนตัวของนักเรียน การตัดสินใจขึ้นอยู่กับสิ่งใด', '["ขึ้นอยู่กับคุณครูประจำชั้น","ขึ้นอยู่กับหัวหน้าห้อง","ขึ้นอยู่กับความยินยอมของตัวนักเรียนเอง","เพื่อนมีสิทธิ์หยิบไปได้ทันที"]'::jsonb, '2'::jsonb, 'ดินสอเป็นของใช้ส่วนตัว เจ้าของมีสิทธิ์ในการอนุญาตหรือไม่อนุญาตให้ผู้อื่นยืม', 'easy', '[หน่วยที่ 1] ของใช้ส่วนตนและของใช้ส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'นักเรียนพบว่าไฟในห้องน้ำโรงเรียนเปิดทิ้งไว้โดยไม่มีใครใช้ ควรทำอย่างไร', '["เดินผ่านไปเพราะไม่ใช่เรื่องของเรา","ตะโกนบอกให้เพื่อนทั้งโรงเรียนรู้","รอให้คุณครูมาเห็นก่อน","ไปปิดสวิตช์ไฟเพื่อช่วยประหยัดพลังงานส่วนรวม"]'::jsonb, '3'::jsonb, 'การช่วยปิดไฟเมื่อไม่มีใครใช้งานเป็นการดูแลรักษาทรัพย์สินส่วนรวมและช่วยประหยัดพลังงาน', 'easy', '[หน่วยที่ 1] การไม่นำของส่วนรวมไปใช้ประโยชน์ส่วนตน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การแซงคิวเพื่อนเพื่อซื้อขนมก่อน ถือเป็นการกระทำแบบใด', '["การเห็นแก่ประโยชน์ส่วนตนมากกว่าส่วนรวม","การเป็นคนฉลาดและคล่องแคล่ว","การรักษาสิทธิ์ของตนเอง","การประหยัดเวลาอย่างคุ้มค่า"]'::jsonb, '0'::jsonb, 'การแซงคิวเป็นการละเมิดสิทธิของผู้อื่นที่มาก่อน เพื่อเอาเปรียบและเห็นแก่ประโยชน์ส่วนตน', 'easy', '[หน่วยที่ 1] การคิดแยกแยะผลประโยชน์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นการปฏิบัติตนที่ถูกต้องในการใช้ห้องสมุดโรงเรียน', '["ฉีกรูปภาพสวยๆ จากหนังสือมาเก็บไว้","อ่านหนังสือเสร็จแล้วนำไปวางไว้ที่จุดพักหนังสือหรือชั้นเดิม","ขีดเขียนชื่อตนเองลงในหน้าปกหนังสือ","นำขนมเข้าไปรับประทานขณะอ่านหนังสือ"]'::jsonb, '1'::jsonb, 'การวางหนังสือคืนที่หรือจุดพักหนังสือช่วยให้ผู้ใช้บริการคนอื่นค้นหาได้ง่ายและรักษาความเป็นระเบียบ', 'easy', '[หน่วยที่ 1] การใช้ประโยชน์จากทรัพย์สินส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การใช้คอมพิวเตอร์ในห้องปฏิบัติการคอมพิวเตอร์ของโรงเรียน ควรใช้ทำสิ่งใด', '["ดาวน์โหลดภาพยนตร์ส่วนตัวเก็บไว้ในแฟลชไดรฟ์","แอบเล่นเกมออนไลน์ส่วนตัวตลอดชั่วโมง","ค้นคว้าข้อมูลบทเรียนตามที่คุณครูมอบหมาย","แกะปุ่มคีย์บอร์ดมาสลับเล่น"]'::jsonb, '2'::jsonb, 'คอมพิวเตอร์โรงเรียนมีไว้เพื่อการศึกษาค้นคว้าตามวัตถุประสงค์ของการจัดการเรียนการสอน', 'easy', '[หน่วยที่ 1] การไม่นำของส่วนรวมไปใช้ประโยชน์ส่วนตน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ระบบคิดฐานสอง (Digital Thinking) ในการต้านทุจริต คือการคิดในลักษณะใด', '["คิดว่าทำผิดนิดหน่อยไม่เป็นไร","คิดหาช่องทางที่ตนเองได้เปรียบ","คิดเฉพาะผลกำไรขาดทุน","คิดแยกแยะว่าสิ่งนี้ \"ถูกหรือผิด\" \"ทำได้หรือทำไม่ได้\""]'::jsonb, '3'::jsonb, 'ระบบคิดฐานสองคือการแยกแยะอย่างเด็ดขาดระหว่างเรื่องส่วนตนกับส่วนรวม อะไรถูก อะไรผิด ทำได้หรือทำไม่ได้ ไม่มีความคลุมเครือ', 'easy', '[หน่วยที่ 1] ระบบคิดฐานสอง (Digital Thinking)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'สถานการณ์ใดในโรงเรียนที่สะท้อนถึง "ผลประโยชน์ทับซ้อน (Conflict of Interest)"', '["กรรมการนักเรียนตัดสินให้กลุ่มเพื่อนสนิทของตนชนะการประกวดพานไหว้ครูทั้งที่ผลงานไม่เรียบร้อย","หัวหน้าห้องจัดเวรทำความสะอาดตามลำดับเลขที่","นักเรียนช่วยครูยกสมุดการบ้านไปส่งที่ห้องพักครู","นักเรียนชวนเพื่อนไปอ่านหนังสือสอบที่ห้องสมุด"]'::jsonb, '0'::jsonb, 'การตัดสินให้กลุ่มเพื่อนตนเองชนะโดยไม่ยึดเกณฑ์ความเป็นธรรม เป็นการเอาความสัมพันธ์ส่วนตนมาทับซ้อนกับหน้าที่ส่วนรวม', 'medium', '[หน่วยที่ 1] ผลประโยชน์ทับซ้อน (Conflict of Interest)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ก้อยเป็นเวรประจำวันทำความสะอาดห้องเรียน แต่รีบกลับบ้านไปดูการ์ตูน จึงแอบหนีกลับ การกระทำของก้อยส่งผลอย่างไร', '["ไม่มีผลกระทบ เพราะห้องเรียนสะอาดอยู่แล้ว","เพื่อนในกลุ่มต้องทำงานหนักขึ้นและห้องเรียนอาจไม่สะอาด","ครูจะชมเชยว่ากลับบ้านตรงเวลา","ก้อยได้ฝึกความคล่องตัวในการหลบเลี่ยง"]'::jsonb, '1'::jsonb, 'การละเลยหน้าที่เวรทำความสะอาดเพื่อประโยชน์ส่วนตน ทำให้เพื่อนร่วมเวรต้องแบกรับภาระเพิ่มขึ้นและเกิดความไม่เป็นธรรม', 'medium', '[หน่วยที่ 1] การคิดแยกแยะผลประโยชน์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การที่พ่อแม่ใช้รถยนต์ส่วนตัวขับไปส่งนักเรียนที่โรงเรียน จัดเป็นการใช้ทรัพย์สินประเภทใด', '["การใช้ทรัพย์สินส่วนรวมเพื่อประโยชน์ส่วนตน","การใช้ทรัพย์สินส่วนรวมเพื่อประโยชน์ส่วนรวม","การใช้ทรัพย์สินส่วนตนเพื่อประโยชน์ส่วนตน","การใช้ทรัพย์สินส่วนตนเพื่อประโยชน์ส่วนรวม"]'::jsonb, '2'::jsonb, 'รถยนต์ของครอบครัวเป็นทรัพย์สินส่วนบุคคล และการรับส่งลูกเป็นกิจการภายในครอบครัว จึงเป็นเรื่องส่วนตนเพื่อประโยชน์ส่วนตน', 'medium', '[หน่วยที่ 1] ทรัพย์สินส่วนรวมและส่วนบุคคล'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากเจ้าหน้าที่นำรถกระบะของทางราชการหรือโรงเรียนไปขนย้ายเฟอร์นิเจอร์ส่วนตัวในวันหยุด ถือเป็นการกระทำอย่างไร', '["ทำได้เพราะเป็นวันหยุดราชการ","เป็นสิทธิพิเศษของผู้ดูแลรถยนต์","ทำได้หากเติมน้ำมันคืนให้หลวง","ไม่ถูกต้อง เพราะเป็นการนำทรัพย์สินส่วนรวมของหลวงไปใช้เพื่อประโยชน์ส่วนตัว"]'::jsonb, '3'::jsonb, 'ทรัพย์สินของราชการมีไว้เพื่อภารกิจของส่วนรวม การนำไปใช้ส่วนตัวแม้ในวันหยุดก็ถือว่าผิดหลักการและเป็นการทุจริต', 'medium', '[หน่วยที่ 1] ทรัพย์สินส่วนรวมและส่วนบุคคล'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'นักเรียนคนใดใช้ "ระบบคิดฐานสอง" (แยกแยะถูก-ผิดเด็ดขาด) ได้ถูกต้องที่สุด', '["บอยคิดว่าแม้เป็นเงินแค่ 1 บาทของผู้อื่นตกอยู่ ก็ไม่ใช่ของเรา จึงนำไปส่งคุณครูประกาศหาเจ้าของ","เอกคิดว่าเก็บเงินได้ 5 บาทไม่ต้องส่งครู แต่ถ้า 100 บาทค่อยส่ง","เจนคิดว่าลอกการบ้านเพื่อนวิชาเดียวไม่เป็นไร เพราะไม่ได้ลอกข้อสอบ","ดาวคิดว่าหยิบชอล์กของโรงเรียนกลับบ้านแท่งเดียวโรงเรียนไม่เดือดร้อน"]'::jsonb, '0'::jsonb, 'ระบบคิดฐานสองไม่ใช้ปริมาณเงินมาตัดสินความถูกผิด เงินแม้เพียง 1 บาทหากไม่ใช่ของเราก็คือไม่ใช่ของเรา ต้องส่งคืน', 'medium', '[หน่วยที่ 1] ระบบคิดฐานสอง (Digital Thinking)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'นักเรียนได้รับมอบหมายให้เป็นผู้แจกนมโรงเรียนให้กับเพื่อนๆ ในห้อง พฤติกรรมใดแสดงถึงความซื่อสัตย์และไม่มีผลประโยชน์ทับซ้อน', '["เก็บกล่องนมที่มีสภาพดีที่สุดไว้ให้ตนเองและเพื่อนสนิท","แจกนมให้ทุกคนอย่างเท่าเทียมตามรายชื่อ ไม่เลือกที่รักมักที่ชัง","แจกให้นักเรียนที่นำขนมมาแบ่งให้ตนเองก่อน","เก็บนมกล่องที่เหลือกลับบ้านไปให้พี่น้องโดยไม่แจ้งครู"]'::jsonb, '1'::jsonb, 'การปฏิบัติหน้าที่ด้วยความเป็นกลาง เท่าเทียม และโปร่งใส ไม่เอื้อประโยชน์แก่ตนเองหรือเพื่อนสนิท เป็นการป้องกันผลประโยชน์ทับซ้อน', 'medium', '[หน่วยที่ 1] ผลประโยชน์ทับซ้อน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นการกระทำที่ทำให้ "ทรัพย์สินส่วนรวม" เสื่อมค่าและชำรุดเสียหายเร็วขึ้น', '["ใช้โต๊ะเก้าอี้เรียนหนังสือและช่วยกันเช็ดฝุ่น","นั่งเก้าอี้ด้วยความระมัดระวัง 4 ขาแตะพื้น","ใช้ลิควิดหรือปากกาขูดขีดเขียนชื่อหรือข้อความลงบนโต๊ะเรียน","ช่วยกันปิดหน้าต่างห้องเรียนเมื่อฝนตก"]'::jsonb, '2'::jsonb, 'การขีดเขียนโต๊ะเรียนเป็นการทำลายทรัพย์สินส่วนรวม ทำให้โต๊ะสกปรก ชำรุด และโรงเรียนต้องเสียงบประมาณซ่อมแซม', 'medium', '[หน่วยที่ 1] การใช้ประโยชน์จากทรัพย์สินส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การนำโทรศัพท์มือถือส่วนตัวมาชาร์จแบตเตอรี่ที่ปลั๊กไฟห้องเรียนเพื่อเล่นเกมส่วนตัว ควรพิจารณาอย่างไร', '["เป็นเรื่องปกติที่ใครๆ ก็ทำได้","หากชาร์จไม่เกิน 30 นาทีถือว่าไม่ผิด","ทำได้ตลอดเวลาเพราะโรงเรียนมีงบประมาณเหลือเฟือ","เป็นการเบียดเบียนไฟฟ้าซึ่งเป็นงบประมาณส่วนรวมของโรงเรียนเพื่อความบันเทิงส่วนตน"]'::jsonb, '3'::jsonb, 'ไฟฟ้าของโรงเรียนมีไว้เพื่อสนับสนุนการจัดการศึกษา การชาร์จแบตเตอรี่เพื่อเล่นเกมส่วนตัวถือเป็นการใช้ประโยชน์ส่วนรวมเพื่อความเพลิดเพลินส่วนตัว', 'medium', '[หน่วยที่ 1] การคิดแยกแยะผลประโยชน์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อมีการเลือกตั้งประธานนักเรียน การลงคะแนนเสียงควรยึดถือสิ่งใดเป็นสำคัญที่สุด', '["เลือกผู้สมัครที่มีความรู้ ความสามารถ ซื่อสัตย์ และทำประโยชน์เพื่อส่วนรวมได้จริง","เลือกผู้สมัครที่สัญญาว่าจะแจกขนมให้เรา","เลือกเพื่อนสนิทในกลุ่มเดียวกันเสมอ","เลือกคนที่หน้าตาดีและแต่งตัวสวยงาม"]'::jsonb, '0'::jsonb, 'การเลือกผู้นำต้องยึดประโยชน์ของโรงเรียนและนักเรียนทุกคนเป็นหลัก โดยเลือกคนดี มีความสามารถ และมีความซื่อสัตย์', 'medium', '[หน่วยที่ 1] ผลประโยชน์ส่วนตนและส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดอธิบายความหมายของ "ผลประโยชน์ส่วนรวม" ได้ถูกต้องที่สุด', '["สิ่งที่เป็นประโยชน์ต่อตัวเราและครอบครัวของเราเท่านั้น","สิ่งที่เป็นประโยชน์ร่วมกันของคนทุกคนในสังคม ชุมชน หรือประเทศชาติ","สิ่งที่เป็นประโยชน์ต่อคนกลุ่มใดกลุ่มหนึ่งที่มีอำนาจ","สิ่งของที่เราสามารถนำกลับไปใช้ที่บ้านได้ตลอดเวลา"]'::jsonb, '1'::jsonb, 'ประโยชน์ส่วนรวมคือผลประโยชน์ที่คนทุกคนในสังคมได้รับร่วมกัน เช่น ความสงบเรียบร้อย สวนสาธารณะ ถนนหนทาง และโรงเรียน', 'medium', '[หน่วยที่ 1] การคิดแยกแยะผลประโยชน์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'แม่ของแป้งเป็นครู และโรงเรียนมีเครื่องถ่ายเอกสาร แป้งควรทำอย่างไรเมื่อต้องการถ่ายเอกสารรายงานกลุ่มของตนเอง', '["แอบนำกระดาษและเครื่องถ่ายเอกสารของโรงเรียนมาถ่ายฟรีในตอนเย็น","บอกให้แม่ถ่ายเอกสารให้ในเวลาราชการเพราะเป็นลูกครู","ขออนุญาตใช้เครื่องและนำกระดาษของตนเองมา หรือไปใช้บริการร้านถ่ายเอกสารภายนอกตามระเบียบ","นำเอกสารของเพื่อนทั้งห้องมาให้แม่ถ่ายฟรีทั้งหมด"]'::jsonb, '2'::jsonb, 'การไม่ใช้สิทธิ์ส่วนตัวเบียดเบียนทรัพยากรของโรงเรียน และปฏิบัติตามระเบียบอย่างถูกต้อง แสดงถึงความซื่อสัตย์สุจริต', 'medium', '[หน่วยที่ 1] การไม่นำของส่วนรวมไปใช้ประโยชน์ส่วนตน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การเปิดพัดลมในห้องเรียน ควรมีแนวทางปฏิบัติอย่างไรให้เกิดประโยชน์สูงสุดต่อส่วนรวม', '["เปิดเฉพาะตัวที่พัดตรงมาที่โต๊ะตนเองคนเดียว","เปิดเบอร์แรงสุดตลอดเวลาไม่ว่าอากาศจะหนาวหรือร้อน","เปิดทิ้งไว้ตลอดทั้งวันเพื่อระบายอากาศแม้ไม่มีใครอยู่","เปิดพัดลมเมื่อมีคนอยู่ในห้อง และปิดทุกตัวเมื่อไม่มีใครอยู่หรือหมดชั่วโมงเรียน"]'::jsonb, '3'::jsonb, 'การปิดพัดลมเมื่อไม่มีคนอยู่ ช่วยประหยัดค่าไฟฟ้าส่วนรวม และป้องกันการเกิดไฟฟ้าลัดวงจร', 'medium', '[หน่วยที่ 1] การใช้ประโยชน์จากทรัพย์สินส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'นทีเป็นกรรมการตรวจเช็กความสะอาดโต๊ะอาหารในโรงอาหาร หากพบน้องสาวตนเองกินเสร็จแล้วไม่เก็บจาน นทีควรทำอย่างไร', '["ตักเตือนและให้น้องสาวนำจานไปเก็บให้เรียบร้อยตามกฎเช่นเดียวกับทุกคน","แกล้งทำเป็นมองไม่เห็นเพราะเป็นน้องสาวตนเอง","เก็บจานแทนให้น้องสาวทุกวัน","ไปตำหนินักเรียนโต๊ะอื่นแทน"]'::jsonb, '0'::jsonb, 'การปฏิบัติหน้าที่ต้องมีความเที่ยงธรรม ไม่ละเว้นหรือช่วยเหลือคนในครอบครัวหรือคนสนิท', 'medium', '[หน่วยที่ 1] ผลประโยชน์ทับซ้อน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'สีเทียนในกล่องกิจกรรมศิลปะของห้องเรียน ใครมีสิทธิ์ใช้งานได้บ้าง', '["หัวหน้าห้องและรองหัวหน้าห้องเท่านั้น","นักเรียนทุกคนในห้องเรียนตามข้อตกลงและกิจกรรมการเรียนรู้","นักเรียนที่สอบได้คะแนนสูงสุด","นักเรียนที่บริจาคเงินให้ห้องเรียน"]'::jsonb, '1'::jsonb, 'ของใช้ส่วนรวมของห้องเรียน นักเรียนทุกคนในห้องมีสิทธิ์เข้าถึงและใช้งานอย่างเสมอภาคตามกติกา', 'medium', '[หน่วยที่ 1] ของใช้ส่วนตนและของใช้ส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'พฤติกรรมใดแสดงถึงการ "คำนึงถึงส่วนรวมมาก่อนส่วนตน"', '["เลือกที่นั่งแถวหน้าสุดเพื่อดูจอชัดๆ โดยไม่สนใจคนข้างหลัง","รีบวิ่งไปตักอาหารให้เต็มจานก่อนคนอื่น","แบ่งปันพื้นที่ร่มเงาให้เพื่อนร่วมยืนขณะเข้าแถวตากแดดในตอนเช้า","เก็บลูกบาสเกตบอลไว้เล่นคนเดียวไม่ให้เพื่อนร่วมทีม"]'::jsonb, '2'::jsonb, 'การเอื้อเฟื้อพื้นที่และนึกถึงความสะดวกสบายของผู้อื่นร่วมกัน แสดงถึงการมีจิตสาธารณะเห็นแก่ส่วนรวม', 'medium', '[หน่วยที่ 1] การคิดแยกแยะผลประโยชน์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อใช้ห้องน้ำของโรงเรียน สิ่งใดที่ไม่ควรปฏิบัติเป็นอย่างยิ่ง', '["กดชักโครกหรือราดน้ำให้สะอาดทุกครั้งหลังใช้งาน","ตรวจดูความสะอาดก่อนเดินออกจากห้องน้ำ","ล้างมือด้วยสบู่หลังจากเสร็จธุระ","ทิ้งกระดาษชำระหรือผ้าอนามัยลงในโถส้วมจนเกิดการอุดตัน"]'::jsonb, '3'::jsonb, 'การทิ้งสิ่งของที่ย่อยสลายยากลงในโถส้วมทำให้ท่ออุดตัน ส่งผลกระทบต่อผู้อื่นที่ต้องมาใช้ต่อ และโรงเรียนต้องเสียค่าใช้จ่ายซ่อมแซม', 'medium', '[หน่วยที่ 1] การใช้ประโยชน์จากทรัพย์สินส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'คำกล่าวที่ว่า "เก็บดอกไม้ในสวนสาธารณะมาประดับแจกันที่บ้านเพียงดอกเดียว ไม่เป็นไรหรอก" มีข้อผิดพลาดในแง่คิดอย่างไร', '["ผิดพลาด เพราะหากทุกคนคิดเหมือนกัน ดอกไม้ในสวนสาธารณะก็จะถูกเด็ดจนหมดและคนอื่นจะไม่ได้ชมความงาม","ไม่ผิดพลาด เพราะดอกไม้มีจำนวนมาก","ไม่ผิดพลาด เพราะเป็นการนำมาใช้ประโยชน์ ดีกว่าปล่อยให้ร่วงโรย","ผิดพลาดเฉพาะถ้ามีคนเห็นเท่านั้น"]'::jsonb, '0'::jsonb, 'สวนสาธารณะเป็นของส่วนรวม หากทุกคนคิดเอาประโยชน์ส่วนตนเพียงเล็กน้อย ทรัพย์สินส่วนรวมก็จะถูกทำลายจนหมดสิ้น', 'medium', '[หน่วยที่ 1] การคิดแยกแยะผลประโยชน์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หลักการคิดแบบ "ระบบคิดฐานสิบ" ที่ทำให้เกิดการทุจริต มีลักษณะอย่างไร', '["การคิดแบบแยกถูก-ผิด ชัดเจน 100%","การคิดปะปนระหว่างเรื่องส่วนตนกับส่วนรวม หยวนๆ ยอมรับการทุจริตเล็กๆ น้อยๆ ได้","การใช้คณิตศาสตร์คำนวณเงินอย่างรอบคอบ","การทำงานร่วมกับเพื่อน 10 คนอย่างเป็นระบบ"]'::jsonb, '1'::jsonb, 'ระบบคิดฐานสิบในการทุจริตคือการประนีประนอมกับความผิด คิดว่าโกงนิดหน่อยไม่เป็นไร หรือคิดแบบผลประโยชน์ทับซ้อน', 'medium', '[หน่วยที่ 1] ระบบคิดฐานสอง (Digital Thinking)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การยืมหนังสือจากห้องสมุดโรงเรียนแล้วไม่ยอมนำมาคืนตามกำหนด ส่งผลเสียอย่างไรมากที่สุด', '["ทำให้เรามีหนังสืออ่านตลอดเวลา","ทำให้ห้องสมุดมีพื้นที่วางหนังสือเล่มใหม่ง่ายขึ้น","ตัดโอกาสผู้อื่นที่ต้องการศึกษาค้นคว้าข้อมูลจากหนังสือนั้น","ไม่มีผลเสียใดๆ เกิดขึ้น"]'::jsonb, '2'::jsonb, 'การกักเก็บหนังสือส่วนรวมไว้เป็นของตนเองนานเกินกำหนด ทำให้เพื่อนนักเรียนคนอื่นเสียโอกาสในการเรียนรู้', 'medium', '[หน่วยที่ 1] การไม่นำของส่วนรวมไปใช้ประโยชน์ส่วนตน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'คุณครูให้คะแนนการประกวดวาดภาพ หากครูให้คะแนนบุตรหลานของตนเองเป็นที่หนึ่งทั้งที่ภาพไม่สวยงาม ครูขาดสิ่งใด', '["ขาดทักษะทางศิลปะ","ขาดความรักต่อเด็กนักเรียนคนอื่น","ขาดเวลาในการตัดสิน","ขาดความซื่อสัตย์และความเป็นกลาง (เกิดผลประโยชน์ทับซ้อน)"]'::jsonb, '3'::jsonb, 'การตัดสินโดยเอาความสัมพันธ์ส่วนตัวมาเกี่ยวข้อง ทำให้ขาดความเป็นกลาง เกิดความอยุติธรรมและผลประโยชน์ทับซ้อน', 'medium', '[หน่วยที่ 1] ผลประโยชน์ทับซ้อน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในโครงการอาหารกลางวันของโรงเรียน หากแม่ครัวนำวัตถุดิบเนื้อสัตว์และผักที่เหลือจากการปรุงอาหารกลับไปทำกินที่บ้านทุกวัน พฤติกรรมนี้เข้าข่ายข้อใด', '["เป็นการเบียดเบียนทรัพย์สินของราชการเพื่อประโยชน์ส่วนตน เป็นการทุจริตต่อหน้าที่","เป็นการประหยัดทรัพยากรเพื่อไม่ให้อาหารเน่าเสีย","เป็นสวัสดิการทั่วไปของแม่ครัวที่ไม่ผิดระเบียบ","เป็นการแสดงความรับผิดชอบในการกำจัดเศษอาหาร"]'::jsonb, '0'::jsonb, 'วัตถุดิบอาหารกลางวันซื้อด้วยงบประมาณแผ่นดินเพื่อเด็กนักเรียน การนำกลับบ้านโดยมิชอบถือเป็นการยักยอกทรัพย์สินส่วนรวม', 'hard', '[หน่วยที่ 1] การวิเคราะห์ผลประโยชน์ส่วนตนและส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'พิจารณาข้อความ: "การจอดรถยนต์ส่วนบุคคลขวางทางเข้า-ออกของโรงพยาบาลหรือโรงเรียน เพื่อความสะดวกของตนเองเพียง 5 นาที" การกระทำนี้สะท้อนปัญหาใดในระดับโครงสร้างสังคม', '["การขาดทักษะในการขับขี่รถยนต์","การให้ความสำคัญกับความสะดวกสบายส่วนตนเหนือความปลอดภัยและความเป็นระเบียบของส่วนรวม","ปัญหาการจราจรที่เกิดจากการออกแบบถนนแคบเกินไป","การบริหารเวลาที่คุ้มค่าของผู้ขับขี่"]'::jsonb, '1'::jsonb, 'การเห็นแก่ความสะดวกของตนเองแม้เพียงระยะเวลาสั้นๆ โดยละเลยผลกระทบต่อผู้อื่น สะท้อนถึงการขาดจิตสำนึกต่อส่วนรวม', 'hard', '[หน่วยที่ 1] การวิเคราะห์ผลประโยชน์ส่วนตนและส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การปรับเปลี่ยนกระบวนการคิดของคนในชาติจาก "ระบบคิดฐานสิบ" มาเป็น "ระบบคิดฐานสอง" มีเป้าหมายสูงสุดเพื่ออะไร', '["เพื่อให้นักเรียนทุกคนเก่งวิชาคณิตศาสตร์และคอมพิวเตอร์","เพื่อให้ประชาชนปฏิบัติตามคำสั่งของเจ้าหน้าที่รัฐโดยไม่มีข้อโต้แย้ง","เพื่อสร้างวัฒนธรรมที่แยกผลประโยชน์ส่วนตนออกจากผลประโยชน์ส่วนรวมอย่างเด็ดขาด นำไปสู่สังคมสุจริต","เพื่อลดจำนวนข้าราชการและลดขนาดองค์กรของรัฐ"]'::jsonb, '2'::jsonb, 'เป้าหมายหลักของระบบคิดฐานสองคือการปลูกฝังค่านิยมไม่ทนต่อการโกงและแยกแยะเรื่องส่วนตนกับส่วนรวมได้ชัดเจน', 'hard', '[หน่วยที่ 1] ระบบคิดฐานสองขั้นสูง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'นักเรียนชั้น ป.4 จัดทำโครงงานจำหน่ายน้ำสมุนไพรในงานโรงเรียน หากหัวหน้ากลุ่มนำเงินกำไรไปซื้อขนมกินเองโดยไม่แจกแจงบัญชีให้สมาชิกในกลุ่มทราบ พฤติกรรมนี้ตรงกับข้อใดมากที่สุด', '["การขาดทักษะทางการค้าขาย","การประหยัดเวลาในการทำบัญชี","การบริหารเงินเพื่อการเติบโตของธุรกิจ","การขาดความโปร่งใสและนำผลประโยชน์ของกลุ่มไปเป็นของตนเองโดยมิชอบ"]'::jsonb, '3'::jsonb, 'เงินกำไรเป็นของกลุ่ม การนำไปใช้คนเดียวโดยไม่เปิดเผยบัญชีถือเป็นการขาดความโปร่งใสและทุจริตต่อสมาชิกกลุ่ม', 'hard', '[หน่วยที่ 1] ผลประโยชน์ทับซ้อนขั้นสูง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากนักเรียนพบว่าเพื่อนแอบนำกระดาษ A4 ของห้องเรียนไปใช้ปริ้นการ์ตูนส่วนตัวจนกระดาษหมด และเพื่อนบอกว่า "ช่วยปิดเป็นความลับหน่อย เราเป็นเพื่อนกันนะ" นักเรียนควรมีท่าทีอย่างไรตามหลักจริยธรรม', '["ปฏิเสธการช่วยปกปิดความผิด และแนะนำให้เพื่อนนำกระดาษมาคืนหรือแจ้งครูด้วยความสุภาพ","ขอร่วมปริ้นการ์ตูนด้วยเพื่อจะได้รับผลประโยชน์ร่วมกัน","ยอมช่วยปิดเป็นความลับเพราะมิตรภาพสำคัญกว่าสิ่งของ","นำเรื่องไปโพสต์ประจานเพื่อนในโซเชียลมีเดียทันที"]'::jsonb, '0'::jsonb, 'มิตรภาพที่แท้จริงต้องตั้งอยู่บนความถูกต้อง การเตือนเพื่อนให้รับผิดชอบและไม่สนับสนุนการทำผิดคือสิ่งที่ถูกต้อง', 'hard', '[หน่วยที่ 1] การวิเคราะห์ผลประโยชน์ส่วนตนและส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การใช้ " Wi-Fi ฟรีของโรงเรียน" เพื่อวัตถุประสงค์ใดที่สอดคล้องกับคุณธรรมในการใช้ทรัพยากรสาธารณะมากที่สุด', '["ดาวน์โหลดเกมขนาดใหญ่ข้ามคืนจนอินเทอร์เน็ตโรงเรียนช้าลง","สืบค้นข้อมูลทำโครงงานวิทยาศาสตร์และเปิดคลิปการสอนบทเรียนภาษาอังกฤษ","ดูซีรีส์เกาหลีแบบคมชัดสูงสุดในเวลาพักกลางวัน","เปิดสตรีมมิ่งสดขายของเล่นออนไลน์ส่วนตัว"]'::jsonb, '1'::jsonb, 'อินเทอร์เน็ตโรงเรียนมีวัตถุประสงค์เพื่อการเรียนรู้ การใช้เพื่อการศึกษาช่วยให้เกิดประโยชน์สูงสุดต่อตนเองและคุ้มค่างบประมาณ', 'hard', '[หน่วยที่ 1] การวิเคราะห์ผลประโยชน์ส่วนตนและส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นตัวอย่างของ "การนำเวลาของส่วนรวมไปใช้ประโยชน์ส่วนตน" ในบริบทของนักเรียน', '["การทำการบ้านในชั่วโมงว่างหลังเลิกเรียน","การมาโรงเรียนก่อนเวลาเข้าแถวเพื่อทบทวนหนังสือ","การแอบเล่นเกมบนโต๊ะเรียนขณะที่คุณครูกำลังสอนบทเรียนสำคัญหน้าห้อง","การช่วยคุณครูจัดบอร์ดนิทรรศการในเวลาพักกลางวัน"]'::jsonb, '2'::jsonb, 'ชั่วโมงเรียนเป็นเวลาที่ทุกคนต้องใช้ร่วมกันเพื่อการเรียนรู้ การแอบเล่นเกมทำให้เสียเวลาเรียนและอาจรบกวนสมาธิเพื่อน', 'hard', '[หน่วยที่ 1] การวิเคราะห์ผลประโยชน์ส่วนตนและส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เหตุใด "การคิดแยกแยะประโยชน์ส่วนตนและส่วนรวม" จึงเป็นบันไดขั้นแรกที่สำคัญที่สุดในการป้องกันการทุจริต', '["เพราะทำให้เราสามารถจับผิดผู้อื่นได้เก่งขึ้น","เพราะช่วยให้สอบผ่านวิชาสังคมศึกษาได้คะแนนเต็ม","เพราะเป็นกฎหมายที่มีบทลงโทษจำคุกรุนแรงที่สุด","เพราะหากคนในสังคมไม่สามารถแยกแยะได้ว่าอะไรคือของตน อะไรคือของส่วนรวม ก็จะเกิดการหยิบฉวยทรัพย์สินส่วนรวมไปใช้โดยไม่รู้สึกผิด"]'::jsonb, '3'::jsonb, 'จุดเริ่มต้นของการโกงมักมาจากการไม่รู้หรือไม่แยกแยะระหว่างสิทธิ์ของตนกับสิทธิ์ส่วนรวม เมื่อแยกแยะได้ชัดเจน ย่อมไม่กล้าละเมิด', 'hard', '[หน่วยที่ 1] การคิดแยกแยะผลประโยชน์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดคือตัวอย่างของ "การทุจริตในการเรียน" ที่ไม่ควรทำเด็ดขาด', '["แอบลอกการบ้านเพื่อนมาส่งครู","ถามครูเมื่อไม่เข้าใจบทเรียน","อ่านหนังสือทบทวนก่อนสอบ","ช่วยเพื่อนติวหนังสือก่อนสอบ"]'::jsonb, '0'::jsonb, 'การลอกการบ้านเป็นการหลอกลวงทั้งครูและตนเอง ทำให้ไม่ได้ฝึกฝนทักษะความรู้จริง และเป็นการละเมิดความซื่อสัตย์', 'easy', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อนักเรียนกำลังทำข้อสอบแล้วเพื่อนข้างๆ ยื่นกระดาษคำตอบมาให้ดู นักเรียนควรทำอย่างไร', '["รีบลอกคำตอบลงในกระดาษข้อสอบของตนเองทันที","ปฏิเสธไม่ดู และตั้งใจทำข้อสอบด้วยความสามารถของตนเอง","ส่งกระดาษคำตอบต่อไปให้เพื่อนคนอื่น","หยิบกระดาษนั้นเก็บใส่กระเป๋าเสื้อไว้"]'::jsonb, '1'::jsonb, 'การปฏิเสธการทุจริตในห้องสอบแสดงถึงความซื่อสัตย์และความละอายต่อการกระทำผิด', 'easy', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากพบเห็นเพื่อนนักเรียนแอบขโมยดินสอของผู้อื่น ควรปฏิบัติตนอย่างไร', '["ช่วยเพื่อนดูต้นทางให้","ไม่สนใจเพราะไม่ใช่ดินสอของเรา","บอกตักเตือนเพื่อนให้เอาไปคืน หรือแจ้งคุณครูให้ทราบ","ขอแบ่งดินสอมาใช้ด้วยครึ่งหนึ่ง"]'::jsonb, '2'::jsonb, 'ความไม่ทนต่อการทุจริตคือการไม่นิ่งเฉยเมื่อพบเห็นการกระทำผิด และกล้าที่จะตักเตือนหรือแจ้งผู้รับผิดชอบ', 'easy', '[หน่วยที่ 2] ความไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ความรู้สึก "ละอายใจ" ต่อการทำผิด หมายถึงความรู้สึกอย่างไร', '["รู้สึกอายที่ไม่มีเสื้อผ้าสวยใส่","รู้สึกกลัวว่าจะไม่ได้คะแนนดี","รู้สึกขี้อายไม่กล้าพูดหน้าชั้นเรียน","รู้สึกไม่สบายใจ รังเกียจ และไม่ต้องการทำในสิ่งที่ผิดศีลธรรมหรือกฎระเบียบ"]'::jsonb, '3'::jsonb, 'ความละอายใจ (หิริ) คือความรู้สึกเกรงกลัวและรังเกียจต่อบาปหรือการทำชั่ว แม้จะไม่มีใครเห็นก็ตาม', 'easy', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การเล่นเกมหรือการแข่งขันกีฬาที่แสดงถึง "น้ำใจนักกีฬาและความซื่อสัตย์" คือข้อใด', '["ยอมรับคำตัดสินของกรรมการและไม่โกงกติกา","แอบเหยียบเส้นเขตแดนเมื่อกรรมการเผลอ","พยายามแกล้งทำฟาล์วคู่ต่อสู้ให้บาดเจ็บ","พูดจาเยาะเย้ยทีมที่พ่ายแพ้"]'::jsonb, '0'::jsonb, 'น้ำใจนักกีฬาคือการเคารพกฎ กติกา ซื่อสัตย์ต่อการแข่งขัน และยอมรับผลการแข่งขันอย่างมีสปิริต', 'easy', '[หน่วยที่ 2] ความซื่อสัตย์ในการเล่นกีฬา'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อแม่ค้าทอนเงินเกินมาให้ 20 บาท พฤติกรรมที่ถูกต้องของคนซื่อสัตย์คือข้อใด', '["รีบนำเงินส่วนเกินนั้นไปซื้อไอศกรีมกิน","รีบบอกแม่ค้าและคืนเงินทอนส่วนที่เกินทันที","แอบเก็บใส่กระเป๋าเพราะถือเป็นโชคดี","นำเงินไปหยอดตู้บริจาคเพื่อทำบุญ"]'::jsonb, '1'::jsonb, 'เงินทอนที่เกินมาไม่ใช่เงินของเรา การคืนเงินให้แม่ค้าทันทีแสดงถึงความซื่อสัตย์สุจริตอย่างแท้จริง', 'easy', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การ "ไม่ทนต่อการทุจริต" เริ่มต้นได้ง่ายที่สุดจากสถานที่ใด', '["รอให้โตเป็นผู้ใหญ่ก่อนค่อยทำ","ต้องรอไปทำที่ศาลยุติธรรมเท่านั้น","ที่โรงเรียนและภายในตัวเอง","ทำเฉพาะเวลาที่คุณตำรวจเดินตรวจ"]'::jsonb, '2'::jsonb, 'การสร้างสังคมสุจริตต้องเริ่มต้นที่ตัวเราเองและสิ่งแวดล้อมใกล้ตัว เช่น ที่บ้านและห้องเรียน', 'easy', '[หน่วยที่ 2] ความไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ถ้าครูตรวจข้อสอบผิดแล้วให้คะแนนเราเกินไป 2 คะแนน นักเรียนควรทำอย่างไร', '["เก็บเงียบไว้เพื่อจะได้เกรด 4","ฉีกกระดาษคำตอบข้อนั้นทิ้ง","อวดเพื่อนว่าตนเองโชคดี","นำข้อสอบไปแจ้งคุณครูเพื่อขอให้แก้ไขคะแนนให้ถูกต้องตามจริง"]'::jsonb, '3'::jsonb, 'การแจ้งครูให้แก้ไขคะแนนตามจริงแม้จะทำให้คะแนนลดลง สะท้อนถึงความซื่อสัตย์และความภาคภูมิใจในความสามารถจริงของตน', 'easy', '[หน่วยที่ 2] ความซื่อสัตย์ต่อตนเอง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดไม่ใช่ ผลดีของการเป็นคนที่มีความซื่อสัตย์สุจริต', '["สามารถเอาเปรียบผู้อื่นได้ง่ายขึ้น","มีความภาคภูมิใจในตนเอง","เป็นที่ไว้วางใจของพ่อแม่ ครู และเพื่อนๆ","จิตใจสงบสุข ไม่ต้องหวาดระแวงว่าจะถูกจับผิด"]'::jsonb, '0'::jsonb, 'คนซื่อสัตย์จะไม่คิดเอาเปรียบผู้อื่น การเอาเปรียบเป็นลักษณะของคนทุจริตเห็นแก่ได้', 'easy', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ถ้าเพื่อนสนิทชวนแอบปีนรั้วโรงเรียนออกไปซื้อขนมข้างนอก นักเรียนควรทำอย่างไร', '["ตามใจเพื่อนเพื่อรักษาน้ำใจเพื่อนสนิท","ปฏิเสธและเตือนเพื่อนว่าเป็นสิ่งผิดกฎระเบียบของโรงเรียนและอาจเกิดอันตราย","ช่วยดันหลังเพื่อนให้ปีนข้ามรั้วไป","ไปช่วยเฝ้าดูครูเวรให้เพื่อน"]'::jsonb, '1'::jsonb, 'การรักเพื่อนที่ถูกต้องคือการไม่สนับสนุนให้เพื่อนทำผิดกฎ และกล้าเตือนสติเพื่อน', 'easy', '[หน่วยที่ 2] ความไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การลงชื่อแทนเพื่อนในการเข้าแถวเคารพธงชาติ ถือเป็นการกระทำที่ถูกต้องหรือไม่ เพราะเหตุใด', '["ถูกต้อง เพราะเป็นการช่วยเหลือเพื่อนที่มาสาย","ถูกต้อง หากเพื่อนมีเหตุผลส่วนตัว","ไม่ถูกต้อง เพราะเป็นการโกหกและทุจริตต่อเวลาและระเบียบวินัย","ไม่ถูกต้อง เฉพาะเมื่อครูจับได้เท่านั้น"]'::jsonb, '2'::jsonb, 'การเช็คชื่อแทนกันเป็นการหลอกลวงปกปิดความจริง เป็นการปลูกฝังนิสัยทุจริตตั้งแต่เด็ก', 'easy', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'สำนวนไทยข้อใดที่สอนให้มีความซื่อสัตย์สุจริต', '["ไก่เห็นตีนงู งูเห็นนมไก่","น้ำขึ้นให้รีบตัก","จับปลาสองมือ","ซื่อกินไม่หมด คดกินไม่นาน"]'::jsonb, '3'::jsonb, '"ซื่อกินไม่หมด คดกินไม่นาน" หมายถึง คนซื่อสัตย์ย่อมมีความเจริญยั่งยืน ส่วนคนคดโกงย่อมได้รับผลร้ายในที่สุด', 'easy', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในห้องเรียนมีการจัดกล่อง "สหกรณ์ความซื่อสัตย์" ที่ให้นักเรียนหยิบขนมและหยอดเงินลงกล่องเอง ข้อใดแสดงถึงความซื่อสัตย์ที่สุด', '["หยอดเงินครบตามราคาสินค้าทุกครั้ง แม้จะไม่มีใครมองอยู่ก็ตาม","หยอดเงินครึ่งเดียวเพราะไม่มีคนเฝ้า","หยิบขนมไปก่อนแล้วรอให้มีเงินค่อยมาหยอดสัปดาห์หน้าโดยไม่บอกใคร","หยอดเหรียญปลอมลงไปแทนเงินจริง"]'::jsonb, '0'::jsonb, 'ความซื่อสัตย์ที่แท้จริงคือการทำสิ่งที่ถูกต้องแม้ในเวลาที่ไม่มีใครมองเห็น (Integrity)', 'medium', '[หน่วยที่ 2] พฤติกรรมที่ไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากในชุมชนมีผู้สมัครรับเลือกตั้งนำเงินหรือสิ่งของมาแจกเพื่อขอคะแนนเสียง ชาวบ้านควรปฏิบัติอย่างไรจึงจะถูกต้องตามหลักการต้านทุจริต', '["รับเงินไว้แล้วเลือกคนนั้นตามสัญญา","ไม่รับเงิน ไม่ขายเสียง และแจ้งเบาะแสแก่หน่วยงานที่รับผิดชอบ (กกต.)","รับเงินไว้แต่แอบไปกาเบอร์อื่น","เรียกร้องขอเงินเพิ่มเป็นสองเท่า"]'::jsonb, '1'::jsonb, 'การซื้อสิทธิ์ขายเสียงเป็นจุดเริ่มต้นของการทุจริตคอร์รัปชัน พลเมืองดีต้องไม่รับเงินและไม่ขายเสียงเพื่อรักษาระบอบประชาธิปไตย', 'medium', '[หน่วยที่ 2] การไม่ยอมรับการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การแอบลอกข้อสอบจนได้คะแนนเต็ม ส่งผลกระทบเชิงลบต่อตัวนักเรียนในระยะยาวอย่างไรมากที่สุด', '["ทำให้ครูเสียเวลาตรวจข้อสอบ","ทำให้เพื่อนในห้องอิจฉา","ทำให้นักเรียนเข้าใจผิดว่าตนเองเก่ง และไม่เกิดความรู้ความสามารถที่แท้จริงเพื่อใช้ในอนาคต","ทำให้กระดาษคำตอบเลอะเทอะ"]'::jsonb, '2'::jsonb, 'การทุจริตทำให้สูญเสียโอกาสในการพัฒนาตนเอง กลายเป็นคนขาดความรู้จริงและติดนิสัยพึ่งพาการโกง', 'medium', '[หน่วยที่ 2] ผลกระทบของการลอกข้อสอบ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'คำว่า "ความกล้าหาญทางจริยธรรม (Moral Courage)" ในการต่อต้านการทุจริต หมายถึงข้อใด', '["ความกล้าที่จะชกต่อยกับคนที่ทำผิด","ความกล้าที่จะพูดโกหกเพื่อช่วยเพื่อนสนิท","ความกล้าที่จะกระโดดน้ำช่วยคนจมน้ำ","ความกล้าที่จะยืนหยัดทำสิ่งที่ถูกต้อง แม้จะต้องเผชิญกับความยากลำบากหรือแรงกดดันจากเพื่อน"]'::jsonb, '3'::jsonb, 'ความกล้าหาญทางจริยธรรมคือความกล้าทำในสิ่งที่ถูกต้อง ดีงาม และกล้าปฏิเสธการทำชั่วทุกรูปแบบ', 'medium', '[หน่วยที่ 2] ความกล้าหาญทางจริยธรรม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การ "คัดลอกผลงานการบ้านรายงานจากอินเทอร์เน็ตมาทั้งแผ่น" โดยไม่ระบุแหล่งที่มาและบอกครูว่าเป็นผลงานตนเอง จัดเป็นพฤติกรรมใด', '["การละเมิดทรัพย์สินทางปัญญาและการทุจริตทางวิชาการ","การใช้เทคโนโลยีอย่างชาญฉลาด","การประหยัดเวลาอย่างมีประสิทธิภาพ","การเป็นคนใฝ่รู้ใฝ่เรียน"]'::jsonb, '0'::jsonb, 'การนำผลงานของผู้อื่นมาแอบอ้างเป็นของตน (Plagiarism) ถือเป็นการทุจริตและละเมิดสิทธิของผู้อื่น', 'medium', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อมีการแข่งขันตอบปัญหาวิชาการ หากทีมตรงข้ามทำเอกสารเฉลยตกไว้หน้าโต๊ะเรา สิ่งที่ถูกต้องที่สุดที่ควรทำคือข้อใด', '["รีบเปิดอ่านและท่องจำคำตอบก่อนเริ่มแข่ง","นำเอกสารไปส่งคืนให้คณะกรรมการทันทีโดยไม่เปิดดูเนื้อหาข้างใน","แอบถ่ายรูปเก็บไว้ส่งให้เพื่อนในกลุ่ม","แกล้งทำเป็นเหยียบไว้แล้วเตะไปซ่อนใต้ตู้"]'::jsonb, '1'::jsonb, 'การคืนเอกสารแก่กรรมการโดยไม่เปิดอ่าน แสดงถึงความซื่อสัตย์สุจริตและความยุติธรรมในการแข่งขัน', 'medium', '[หน่วยที่ 2] ความไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากทุกคนในสังคมมีความคิดว่า "โกงได้ไม่เป็นไร ขอให้ตนเองรวยและแบ่งปันให้เราบ้าง" ประเทศชาติจะเป็นอย่างไร', '["ประเทศชาติจะพัฒนาอย่างรวดเร็วและร่ำรวย","ประชาชนทุกคนจะมีความสุขและสามัคคีกัน","ระบบเศรษฐกิจ สังคม และกฎหมายจะล้มเหลว เกิดความเหลื่อมล้ำและไร้ความยุติธรรม","โรงเรียนจะมีงบประมาณสร้างสระว่ายน้ำเพิ่มขึ้น"]'::jsonb, '2'::jsonb, 'การยอมรับการโกงจะนำไปสู่ความเสื่อมโทรมของประเทศ ชาติสูญเสียงบประมาณ และกฎหมายไม่ศักดิ์สิทธิ์', 'medium', '[หน่วยที่ 2] ผลกระทบของการทุจริตต่อสังคม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เหตุใด "ความละอายต่อการทุจริต" จึงต้องสร้างจากภายในจิตใจ ไม่ใช่เพียงเพราะกลัวตำรวจจับ', '["เพราะตำรวจมีหน้าที่จับผู้ร้ายอย่างเดียว","เพราะการสร้างจากจิตใจไม่ต้องเสียเงินซื้ออุปกรณ์","เพราะกฎหมายไม่มีผลบังคับใช้กับเด็กนักเรียน","เพราะหากไม่มีใครเห็นหรือไม่มีกฎหมายควบคุม คนที่ไม่มีความละอายใจจากภายในก็พร้อมจะทุจริตทันที"]'::jsonb, '3'::jsonb, 'ความละอายใจจากภายในเป็นเกราะป้องกันที่แท้จริง ทำให้ไม่ทำความผิดแม้จะอยู่ในที่ลับตาคน', 'medium', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในการต่อคิวซื้อตั๋วภาพยนตร์ หากมีคนเดินมาขอแทรกคิวข้างหน้าเราโดยอ้างว่ารีบมาก เราควรตอบอย่างไรอย่างสุภาพและถูกต้อง', '["กล่าวทักท้วงอย่างสุภาพว่า \"ขอโทษนะคะ ทุกคนก็ต่อแถวตามคิว กรุณาไปต่อท้ายแถวด้วยค่ะ\"","ให้แทรกได้ทันทีเพื่อแสดงความมีน้ำใจ","ผลักคนนั้นออกไปด้วยความโมโห","เดินออกจากแถวกลับบ้านด้วยความหงุดหงิด"]'::jsonb, '0'::jsonb, 'การทักท้วงอย่างสุภาพแต่หนักแน่นเป็นการปกป้องสิทธิ์ของตนเองและรักษากติกาส่วนรวมโดยไม่ใช้ความรุนแรง', 'medium', '[หน่วยที่ 2] การไม่ทนต่อการทุจริตในชีวิตประจำวัน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'พ่อแม่ให้เงินไปซื้อของที่ร้านค้า 100 บาท ของราคา 85 บาท มีเงินทอน 15 บาท ข้อใดเป็นการกระทำที่ซื่อสัตย์', '["บอกพ่อแม่ว่าของราคา 100 บาทพอดี","นำเงินทอน 15 บาทและใบเสร็จส่งคืนให้พ่อแม่ครบถ้วน","แอบเก็บเงินทอนไว้เป็นค่าขนมของตนเองโดยไม่ขออนุญาต","นำเงิน 15 บาทไปแบ่งให้เพื่อนสนิท"]'::jsonb, '1'::jsonb, 'การคืนเงินทอนครบถ้วนแสดงถึงความซื่อสัตย์ในครอบครัว ซึ่งเป็นรากฐานของคุณธรรมในสังคม', 'medium', '[หน่วยที่ 2] ความซื่อสัตย์ในครอบครัว'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในการทำงานกลุ่ม ถ้าสมาชิกคนหนึ่งไม่เคยมาช่วยงานเลย แต่วันส่งรายงานมาขอร้องให้ใส่ชื่อตนเองลงไปด้วย สมาชิกในกลุ่มควรทำอย่างไร', '["ใส่ชื่อให้เพราะสงสารและเป็นเพื่อนสนิทกัน","ใส่ชื่อให้แต่ขอคิดเงินค่าจ้าง 50 บาท","ไม่ใส่ชื่อให้ และชี้แจงเหตุผลให้เพื่อนเข้าใจว่าคะแนนต้องมาจากผลงานและการร่วมมือ พร้อมทั้งปรึกษาครู","ทะเลาะวิวาทกับเพื่อนหน้าห้องเรียน"]'::jsonb, '2'::jsonb, 'การใส่ชื่อคนที่ไม่ทำงานเป็นการทุจริตคะแนน ต้องยึดหลักความถูกต้องและให้เพื่อนเรียนรู้ผลของการละเลยหน้าที่', 'medium', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อพบเห็นรุ่นพี่บังคับขู่กรรโชกเอาเงินค่าขนมจากรุ่นน้องในโรงเรียน นักเรียนควรดำเนินการอย่างไรที่ปลอดภัยและเหมาะสมที่สุด', '["เข้าไปชกต่อยกับรุ่นพี่ทันทีเพื่อช่วยรุ่นน้อง","แกล้งทำเป็นมองไม่เห็นและรีบเดินหนี","ยืนถ่ายคลิปวิดีโอแล้วหัวเราะสนุกสนาน","รีบไปแจ้งครูฝ่ายปกครอง ครูประจำชั้น หรือผู้บริหารโรงเรียนทันที เพื่อให้เข้ามาจัดการ"]'::jsonb, '3'::jsonb, 'การแจ้งครูเป็นวิธีการที่ถูกต้อง ปลอดภัย และช่วยแก้ไขปัญหาได้อย่างมีประสิทธิภาพตามขั้นตอนของโรงเรียน', 'medium', '[หน่วยที่ 2] ความไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การ "ปลอมลายมือชื่อผู้ปกครอง" ในสมุดรายงานผลการเรียน จัดเป็นการกระทำที่ส่งผลร้ายอย่างไร', '["เป็นการทำลายความไว้วางใจระหว่างตนเองกับครอบครัวและโรงเรียน อีกทั้งเป็นความผิดฐานปลอมแปลงเอกสาร","ทำให้ผู้ปกครองภูมิใจโดยไม่ต้องกังวล","ช่วยให้ประหยัดเวลาไม่ต้องรอผู้ปกครองเซ็น","เป็นการฝึกทักษะการคัดลอกลายมือ"]'::jsonb, '0'::jsonb, 'การปลอมลายเซ็นเป็นการหลอกลวงที่ร้ายแรง ทำลายความเชื่อมั่น และเป็นการฝึกนิสัยทุจริตที่ผิดกฎหมาย', 'medium', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในการทดสอบวิ่งเก็บของหรือวิ่ง 50 เมตร การแอบออกตัวก่อนเสียงสัญญาณนกหวีดดัง ถือว่าขาดสิ่งใด', '["ขาดความว่องไว","ขาดความซื่อสัตย์ในการปฏิบัติตามกติกา","ขาดแรงจูงใจในการแข่งขัน","ขาดอุปกรณ์กีฬา"]'::jsonb, '1'::jsonb, 'การแอบออกตัวก่อนเป็นการโกงกติกาเพื่อหวังเอาเปรียบผู้อื่น ขาดความซื่อสัตย์และสปิริตนักกีฬา', 'medium', '[หน่วยที่ 2] ความซื่อสัตย์ในการทดสอบสมรรถภาพ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นลักษณะของ "ห้องเรียนต้านทุจริต" (Anti-Corruption Classroom)', '["ห้องเรียนที่ทุกคนแอบลอกการบ้านกันอย่างเงียบๆ","ห้องเรียนที่ติดกล้องวงจรปิดทุกมุมแต่ไม่มีใครคุยกัน","ห้องเรียนที่เพื่อนๆ ช่วยเตือนกันเมื่อมีคนทำผิด ไม่ยอมรับการลอกงาน และร่วมมือกันดูแลของส่วนรวม","ห้องเรียนที่ให้เฉพาะหัวหน้าห้องเป็นคนตัดสินทุกเรื่อง"]'::jsonb, '2'::jsonb, 'ห้องเรียนต้านทุจริตเกิดจากพลังร่วมกันของทุกคนที่มีค่านิยมความซื่อสัตย์ ไม่ทนต่อการโกง และมีจิตสาธารณะ', 'medium', '[หน่วยที่ 2] การไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อทำการทดลองทางวิทยาศาสตร์ ผลการทดลองออกมาไม่ตรงกับสมมติฐานหรือหนังสือ นักเรียนควรบันทึกผลอย่างไร', '["แอบแก้ตัวเลขผลการทดลองให้เหมือนในหนังสือเพื่อจะได้คะแนนเต็ม","ทิ้งใบบันทึกผลและไม่ส่งงาน","ลอกผลการทดลองของกลุ่มเพื่อนข้างๆ มาส่ง","บันทึกผลตามข้อมูลจริงที่ได้จากการทดลอง แล้วเขียนอภิปรายสาเหตุที่ผลคลาดเคลื่อน"]'::jsonb, '3'::jsonb, 'จรรยาบรรณของนักวิทยาศาสตร์และความซื่อสัตย์คือการบันทึกข้อมูลตามความจริง ไม่ดัดแปลงข้อมูลเพื่อเอาใจใคร', 'medium', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การแสดงออกถึง "การไม่ยอมรับคนโกง" ในระดับนักเรียน ควรปฏิบัติในลักษณะใดที่ถูกต้อง', '["ไม่ยกย่องหรือชื่นชมพฤติกรรมโกง ตักเตือนด้วยเหตุผล และไม่ร่วมมือในการกระทำความผิด","รุมด่าทอและใช้ความรุนแรงทำร้ายร่างกายเพื่อน","ขับไล่เพื่อนออกจากโรงเรียนด้วยตนเอง","นำภาพเพื่อนไปตัดต่อล้อเลียนในโซเชียลมีเดีย"]'::jsonb, '0'::jsonb, 'การไม่ยอมรับคนโกงต้องทำด้วยปัญญาและเหตุผล ไม่สนับสนุนการโกง และไม่ส่งเสริมคนทำผิด โดยไม่ใช้ความรุนแรง', 'medium', '[หน่วยที่ 2] การลงโทษทางสังคม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เด็กชายต้นเก็บกระเป๋าสตางค์ที่มีเงินสด 1,000 บาทได้ในโรงอาหาร แม้จะไม่มีใครเห็น แต่ต้นรู้สึกว่า "ถ้านำไปเป็นของตัวเอง เราจะต้องรู้สึกผิดไปตลอดชีวิต" ความรู้สึกนี้คือสิ่งใด', '["ความตระหนกตกใจ","หิริโอตตัปปะ (ความละอายและเกรงกลัวต่อบาป)","ความเสียดายเงิน","ความกังวลเรื่องการเรียน"]'::jsonb, '1'::jsonb, 'หิริโอตตัปปะเป็นธรรมคุ้มครองโลก ความละอายใจต่อบาปทำให้มนุษย์ยึดมั่นในความถูกต้อง', 'medium', '[หน่วยที่ 2] ความละอายใจต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากครูฝึกซ้อมตอบปัญหาวิชาการแอบนำข้อสอบจริงมาบอกให้นักเรียนท่องจำก่อนไปแข่ง นักเรียนควรมีท่าทีอย่างไร', '["ดีใจเพราะจะได้ชนะและได้เหรียญรางวัลแน่นอน","นำข้อสอบไปขายต่อให้เพื่อนโรงเรียนอื่นเพื่อเอากำไร","รู้สึกไม่สบายใจ เพราะเป็นการแข่งขันที่ไม่ยุติธรรมและผิดจริยธรรม","ชวนครูไปเลี้ยงฉลองล่วงหน้า"]'::jsonb, '2'::jsonb, 'ชัยชนะที่ได้จากการโกงไม่มีเกียรติยศ การตระหนักถึงความไม่เป็นธรรมสะท้อนจิตสำนึกที่ดี', 'medium', '[หน่วยที่ 2] ความไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อเผลอทำแจกันดอกไม้ในห้องเรียนแตกโดยไม่มีใครเห็น การปฏิบัติตนข้อใดแสดงถึงความรับผิดชอบสูงสุด', '["รีบกวาดเศษแจกันไปซ่อนไว้ใต้โต๊ะครู","แกล้งทำเป็นไม่รู้ไม่เห็นเมื่อครูถาม","ชี้บอกครูว่าเห็นแมววิ่งชนแจกันแตก","เดินไปบอกคุณครูด้วยความจริงใจ ขอโทษ และยินดีช่วยทำความสะอาดหรือชดใช้ตามความเหมาะสม"]'::jsonb, '3'::jsonb, 'ความกล้ารับผิดชอบในการกระทำของตนเองและการยอมรับผลที่ตามมาเป็นคุณลักษณะสำคัญของคนซื่อสัตย์', 'medium', '[หน่วยที่ 2] การลงโทษตนเองเมื่อทำผิด'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เหตุใดค่านิยม "ไม่โกงแต่ไม่ยุ่งกับคนโกง (นิ่งเฉย)" จึงยังไม่เพียงพอต่อการขจัดปัญหาการทุจริตในสังคม', '["เพราะการนิ่งเฉยเปิดโอกาสให้คนทุจริตกระทำผิดต่อไปได้โดยไม่มีใครขัดขวางหรือตรวจสอบ ทำให้ปัญหาลุกลาม","เพราะคนไม่โกงมีจำนวนน้อยเกินไป","เพราะกฎหมายกำหนดให้ทุกคนต้องเป็นผู้พิพากษา","เพราะการไม่ยุ่งกับใครทำให้คนอื่นมองว่าหยิ่ง"]'::jsonb, '0'::jsonb, 'คำกล่าวของนักปราชญ์ระบุว่า ความชั่วร้ายจะเติบโตได้เมื่อคนดีนิ่งเฉย การไม่ทนต่อการทุจริตจึงต้องมีบทบาทในการหยุดยั้งด้วย', 'hard', '[หน่วยที่ 2] การวิเคราะห์สถานการณ์ความไม่ทนต่อการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การทุจริตจัดซื้อจัดจ้างในการสร้างถนน ส่งผลกระทบโดยตรงต่อประชาชนอย่างไรมากที่สุด', '["ทำให้มีรถยนต์วิ่งบนถนนมากขึ้น","ทำให้ได้ถนนที่ไม่ได้มาตรฐาน ชำรุดพังง่าย เกิดอุบัติเหตุ และสูญเสียงบประมาณภาษีของประชาชน","ทำให้คนขับรถใช้ความเร็วได้มากขึ้น","ทำให้ต้นไม้ริมทางโตเร็วขึ้น"]'::jsonb, '1'::jsonb, 'การโกงงบประมาณส่งผลให้ใช้วัสดุด้อยคุณภาพ ถนนชำรุดเป็นหลุมบ่อ เป็นอันตรายต่อชีวิตและทรัพย์สินของประชาชน', 'hard', '[หน่วยที่ 2] การวิเคราะห์ผลกระทบระดับประเทศ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากการรายงานพฤติกรรมทุจริตของเพื่อนร่วมชั้นอาจทำให้เราถูกเพื่อนบางคนโกรธหรือแบน นักเรียนควรพิจารณาทางเลือกอย่างไรตามหลักคุณธรรม', '["ยอมตามเพื่อนเพื่อรักษาความสัมพันธ์ เพราะเพื่อนสำคัญที่สุด","ย้ายโรงเรียนหนีปัญหาทันที","ยึดมั่นในความถูกต้อง ปรึกษาครูเพื่อหาทางออกที่ปลอดภัย และตระหนักว่ามิตรภาพที่แท้จริงไม่ควรแลกกับการทำชั่ว","แอบไปร่วมทุจริตด้วยเพื่อสร้างความสนิทสนม"]'::jsonb, '2'::jsonb, 'ความถูกต้องย่อมอยู่เหนือกิเลสส่วนตน การเลือกทำสิ่งที่ถูกต้องแม้จะยากลำบากคือเครื่องพิสูจน์คุณธรรม', 'hard', '[หน่วยที่ 2] การประเมินทางเลือกเชิงจริยธรรม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การสร้างวัฒนธรรม "Zero Tolerance" (ไม่ยอมรับการทุจริตอย่างสิ้นเชิง) ในสถานศึกษามีความหมายตรงกับข้อใด', '["การลงโทษนักเรียนที่ทำผิดด้วยการไล่ออกทั้งหมด","การห้ามไม่ให้นักเรียนพูดคุยกันในโรงเรียน","การสั่งให้นักเรียนสอบซ้ำจนกว่าจะได้คะแนนเต็ม","การไม่ประนีประนอมหรือยอมรับการโกงทุกระดับ ไม่ว่าจะเป็นเรื่องเล็กน้อยเพียงใดก็ตาม"]'::jsonb, '3'::jsonb, 'Zero Tolerance คือนโยบายความอดทนเป็นศูนย์ ไม่ยอมผ่อนปรนให้กับการคดโกงทุกรูปแบบ เพื่อสร้างมาตรฐานสุจริต', 'hard', '[หน่วยที่ 2] วัฒนธรรมองค์กรสุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้ออ้างที่ว่า "ใครๆ เขาก็ทำกันทั้งนั้น ทำไมฉันจะทำบ้างไม่ได้" มีกับดักทางความคิด (Logical Fallacy) ในเรื่องใด', '["การคิดว่าสิ่งที่มีคนทำจำนวนมากจะกลายเป็นสิ่งที่ถูกต้องและชอบธรรม ทั้งที่ความผิดก็ยังคงเป็นความผิดเสมอ","การคิดว่าคนอื่นฉลาดกว่าตนเอง","การให้ความสำคัญกับกฎหมายมากเกินไป","การขาดข้อมูลสถิติที่แน่นอน"]'::jsonb, '0'::jsonb, 'จำนวนคนที่ทำผิดไม่ได้เปลี่ยนความผิดให้กลายเป็นความถูก ความผิดยังคงเป็นสิ่งที่ต้องแก้ไข ไม่ใช่ข้ออ้างในการทำตาม', 'hard', '[หน่วยที่ 2] การวิเคราะห์จิตวิทยาการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การแจ้งเบาะแสการทุจริตอย่างสร้างสรรค์และมีประสิทธิภาพ ควรยึดหลักการใดเป็นสำคัญที่สุด', '["การใช้ความรู้สึกส่วนตัวและความสะใจ","การมีข้อมูล ข้อเท็จจริง และหลักฐานที่ชัดเจน ปราศจากอคติหรือการกลั่นแกล้ง","การกล่าวหาลอยๆ เพื่อให้เกิดความตื่นตระหนก","การส่งข้อความด่าทอโดยไม่ระบุประเด็น"]'::jsonb, '1'::jsonb, 'การตรวจสอบและแจ้งเบาะแสต้องอาศัยข้อเท็จจริงและพยานหลักฐาน เพื่อให้เกิดความเป็นธรรมแก่ทุกฝ่ายและแก้ไขได้ตรงจุด', 'hard', '[หน่วยที่ 2] กลไกการแจ้งเบาะแส'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากคณะกรรมการประเมินโรงเรียนแวะมารับประทานอาหารกลางวันแบบหรูหราที่ผู้บริหารจัดเตรียมไว้เป็นพิเศษก่อนทำการประเมิน อาจก่อให้เกิดข้อสงสัยเรื่องใด', '["ความอร่อยของอาหารในท้องถิ่น","ความสะอาดของห้องครัวโรงเรียน","ความโปร่งใสและอิสระในการประเมินผล ซึ่งอาจเกิดอคติและความเกรงใจจนผลประเมินไม่สะท้อนความจริง","งบประมาณค่าเดินทางของคณะกรรมการ"]'::jsonb, '2'::jsonb, 'การให้การรับรองหรือของกำนัลแก่ผู้ประเมินอาจส่งผลต่อความเป็นกลาง ทำให้เกิดผลประโยชน์ทับซ้อนในการตัดสิน', 'hard', '[หน่วยที่ 2] การวิเคราะห์ผลประโยชน์ทับซ้อนในระบบโรงเรียน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ประวัติศาสตร์หลายยุคหลายสมัยชี้ให้เห็นว่า สาเหตุสำคัญที่สุดที่ทำให้อาณาจักรหรือประเทศชาติล่มสลายลง เกิดจากสิ่งใด', '["สภาพอากาศที่หนาวเย็นเกินไป","การสร้างกำแพงเมืองไม่สูงพอ","การขาดแคลนเทคโนโลยีคอมพิวเตอร์","การทุจริตคอร์รัปชัน การฉ้อราษฎร์บังหลวง และความแตกแยกของคนในชาติ"]'::jsonb, '3'::jsonb, 'การทุจริตและการเอารัดเอาเปรียบทำลายความมั่นคงและความสามัคคี นำไปสู่ความเสื่อมถอยและการล่มสลายของสังคม', 'hard', '[หน่วยที่ 2] การถอดบทเรียนทางประวัติศาสตร์'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ตัวอักษร "S" ในโมเดล STRONG ย่อมาจากคำว่า Sufficient มีความหมายตรงกับข้อใด', '["ความพอเพียง","ความรวดเร็ว","ความเข้มแข็ง","ความฉลาด"]'::jsonb, '0'::jsonb, 'S = Sufficient หมายถึง ความพอเพียง ปฏิบัติตนตามหลักปรัชญาของเศรษฐกิจพอเพียง ไม่โลภ ไม่เบียดเบียนผู้อื่น', 'easy', '[หน่วยที่ 3] โมเดล STRONG - S (Sufficient)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ตัวอักษร "T" ในโมเดล STRONG ย่อมาจาก Transparent หมายถึงสิ่งใด', '["ความอดทนอดกลั้น","ความโปร่งใส ตรวจสอบได้","ความรู้ทันเทคโนโลยี","การท่องเที่ยว"]'::jsonb, '1'::jsonb, 'T = Transparent หมายถึง ความโปร่งใส ตรวจสอบได้ เปิดเผยข้อมูล และดำเนินงานอย่างตรงไปตรงมา', 'easy', '[หน่วยที่ 3] โมเดล STRONG - T (Transparent)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ตัวอักษร "R" ในโมเดล STRONG ย่อมาจาก Realise หมายถึงสิ่งใด', '["การวิ่งออกกำลังกาย","การพักผ่อนหย่อนใจ","ความตระหนักรู้และเข้าใจภัยของการทุจริต","การอ่านหนังสือ"]'::jsonb, '2'::jsonb, 'R = Realise หมายถึง การตระหนักรู้ รู้เท่าทันผลกระทบและความเสียหายที่เกิดจากการทุจริต', 'easy', '[หน่วยที่ 3] โมเดล STRONG - R (Realise)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ตัวอักษร "O" ในโมเดล STRONG ย่อมาจาก Onward มีความหมายถึงการปฏิบัติตนอย่างไร', '["การย้อนกลับไปทำผิดแบบเดิม","การอยู่นิ่งๆ ไม่ทำอะไร","การยอมแพ้ต่ออุปสรรค","การมุ่งไปข้างหน้า พัฒนาตนเองและมุ่งมั่นทำความดีอย่างต่อเนื่อง"]'::jsonb, '3'::jsonb, 'O = Onward หมายถึง การมุ่งมั่นพัฒนาตนเอง สังคม และขับเคลื่อนการต่อต้านการทุจริตไปข้างหน้าอย่างไม่หยุดยั้ง', 'easy', '[หน่วยที่ 3] โมเดล STRONG - O (Onward)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ตัวอักษร "N" ในโมเดล STRONG ย่อมาจากคำว่า Knowledge หมายถึงการมีสิ่งใด', '["มีความรู้ ความเข้าใจในกฎระเบียบและคุณธรรม","มีเงินทองมากมาย","มีเพื่อนสนิทจำนวนมาก","มีของเล่นทันสมัย"]'::jsonb, '0'::jsonb, 'N = Knowledge หมายถึง การมีความรู้เท่าทันกฎหมาย ระเบียบแบบแผน และหลักจริยธรรม', 'easy', '[หน่วยที่ 3] โมเดล STRONG - N (Knowledge)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ตัวอักษร "G" ในโมเดล STRONG ย่อมาจาก Generosity มีความหมายถึงสิ่งใด', '["ความตระหนี่ถี่เหนียว","ความเอื้ออาทร มีน้ำใจแบ่งปัน ไม่เห็นแก่ตัว","ความโกรธแค้น","ความอยากได้ของผู้อื่น"]'::jsonb, '1'::jsonb, 'G = Generosity หมายถึง ความเอื้ออาทร จิตสาธารณะ มีน้ำใจช่วยเหลือผู้อื่นโดยไม่หวังผลประโยชน์ตอบแทน', 'easy', '[หน่วยที่ 3] โมเดล STRONG - G (Generosity)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การปฏิบัติตนตามหลัก "ความพอเพียง" ในระดับนักเรียน ป.4 คือข้อใด', '["รบเร้าให้พ่อแม่ซื้อโทรศัพท์ราคาแพงตามเพื่อน","ไม่อดออมเงินเพราะคิดว่ายังมีเงินใช้อยู่","พอใจในอุปกรณ์การเรียนที่ตนมี ใช้สิ่งของอย่างประหยัดและคุ้มค่า","ซื้อขนมกินจนหมดเงินค่าขนมทุกวัน"]'::jsonb, '2'::jsonb, 'ความพอเพียงคือความพอประมาณ รู้จักคุณค่าของสิ่งของ และไม่ใช้จ่ายเกินฐานะ', 'easy', '[หน่วยที่ 3] ความพอประมาณและความพอเพียง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การกระทำใดของเหรัญญิกห้องเรียนแสดงถึงความ "โปร่งใส (Transparent)"', '["เก็บเงินห้องไว้ในกระเป๋าตนเองโดยไม่จดบันทึก","ปฏิเสธไม่ให้เพื่อนดูยอดเงินห้อง","นำเงินห้องไปซื้อขนมกินส่วนตัวก่อนแล้วค่อยคืน","ทำบัญชีรายรับ-รายจ่ายของห้องเรียนและติดประกาศให้เพื่อนทุกคนตรวจสอบได้"]'::jsonb, '3'::jsonb, 'การทำบัญชีที่ชัดเจนและเปิดเผยให้ทุกคนตรวจสอบได้ เป็นตัวอย่างที่ดีของความโปร่งใส', 'easy', '[หน่วยที่ 3] ความโปร่งใสในห้องเรียน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การที่นักเรียนช่วยสอนการบ้านเพื่อนที่เรียนไม่เข้าใจในช่วงพัก ถือเป็นการปฏิบัติตามหลักการใดของโมเดล STRONG', '["G (ความเอื้ออาทร - Generosity)","T (ความลับ)","S (ความโลภ)","O (ความล่าช้า)"]'::jsonb, '0'::jsonb, 'การสละเวลาและความรู้ช่วยติวเพื่อนด้วยจิตใจเมตตา แสดงถึงความเอื้ออาทร (Generosity)', 'easy', '[หน่วยที่ 3] ความเอื้ออาทรแบ่งปัน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การหยอดกระปุกออมสินทุกวันหลังเลิกเรียน ส่งผลดีต่อนักเรียนอย่างไร', '["ทำให้ไม่มีเงินซื้อขนมอร่อยๆ กิน","สร้างวินัยทางการเงินและมีความพร้อมรับมือเหตุจำเป็นในอนาคต","ทำให้เพื่อนล้อเลียนว่าขี้งก","ไม่มีประโยชน์ต่อการดำเนินชีวิต"]'::jsonb, '1'::jsonb, 'การออมเงินสร้างภูมิคุ้มกันที่ดีในตัวเองตามหลักปรัชญาของเศรษฐกิจพอเพียง', 'easy', '[หน่วยที่ 3] การออมและความพอเพียง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากนักเรียนได้รับมอบหมายให้จัดซื้ออุปกรณ์จัดบอร์ดวันแม่ การนำหลัก "Transparent (ความโปร่งใส)" มาใช้ ควรทำอย่างไร', '["ซื้อของร้านที่แพงที่สุดเพื่อเอาแต้มสะสมส่วนตัว","ทิ้งใบเสร็จและบอกราคาครูคร่าวๆ","เก็บใบเสร็จรับเงินทุกใบและแจกแจงรายการซื้อพร้อมเงินทอนส่งคืนครูอย่างชัดเจน","นำเงินทอนที่เหลือไปแบ่งกับเพื่อนสนิท"]'::jsonb, '2'::jsonb, 'การมีหลักฐานใบเสร็จและแจกแจงรายการเงินทอนครบถ้วนคือหัวใจของความโปร่งใสที่ตรวจสอบได้', 'medium', '[หน่วยที่ 3] การประยุกต์ใช้โมเดล STRONG'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ความ "โลภและความอยากได้อยากมีเกินความจำเป็น" นำไปสู่การทุจริตได้อย่างไร', '["ทำให้คนเราขยันทำงานมากขึ้น","ทำให้ได้รับคำชื่นชมจากสังคม","ทำให้เกิดการประหยัดอดออม","ทำให้คนแสวงหาเงินและทรัพย์สินด้วยวิธีการที่ผิดกฎหมายและคดโกง เพื่อตอบสนองความต้องการของตนเอง"]'::jsonb, '3'::jsonb, 'ความไม่รู้จักพอเป็นต้นตอของการทุจริต เมื่ออยากได้เกินฐานะจึงเกิดแรงจูงใจในการคดโกง', 'medium', '[หน่วยที่ 3] ความพอเพียงกับการป้องกันการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'พฤติกรรมใดแสดงว่านักเรียนมี "Realise (ความตระหนักรู้)" ในปัญหาการทุจริต', '["ตระหนักว่าแม้การโกงเพียงเล็กน้อย เช่น การลอกข้อสอบ ก็ทำลายคุณค่าในตนเองและส่งผลต่อสังคมในอนาคต","คิดว่าการโกงเป็นเรื่องไกลตัว ไม่เกี่ยวข้องกับตนเอง","คิดว่าถ้าไม่มีใครจับได้ก็ไม่ถือว่าเป็นความผิด","คิดว่าผู้ใหญ่เท่านั้นที่มีหน้าที่ป้องกันการทุจริต"]'::jsonb, '0'::jsonb, 'ความตระหนักรู้คือการเห็นความเชื่อมโยงของผลกระทบจากการทุจริต และระมัดระวังตนเองไม่ให้ก้าวสู่การกระทำผิด', 'medium', '[หน่วยที่ 3] โมเดล STRONG - Realise (ความตระหนักรู้)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'กลุ่มนักเรียนแกนนำจัดตั้งชมรม "เยาวชนไทย หัวใจซื่อสัตย์" เพื่อรณรงค์ความซื่อสัตย์ในโรงเรียนอย่างต่อเนื่อง สอดคล้องกับหลักการข้อใด', '["S (Sufficient)","O (Onward)","N (Negative)","T (Tired)"]'::jsonb, '1'::jsonb, 'Onward คือการขับเคลื่อนไปข้างหน้าอย่างมุ่งมั่นและต่อเนื่องเพื่อพัฒนาสิ่งแวดล้อมสุจริต', 'medium', '[หน่วยที่ 3] โมเดล STRONG - Onward (มุ่งไปข้างหน้า)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ตามหลักเศรษฐกิจพอเพียง "การมีภูมิคุ้มกันในตัวที่ดี" ต้านการทุจริต หมายถึงข้อใด', '["การฉีดวัคซีนป้องกันไข้หวัดใหญ่","การมีร่างกายแข็งแรงเล่นกีฬาเก่ง","การมีหลักคิดทางจริยธรรมที่เข้มแข็ง รู้จักยับยั้งชั่งใจ ไม่หลงผิดไปตามสิ่งยั่วยุหรือคำชักจูงของคนชั่ว","การไม่คบค้าสมาคมกับใครเลย"]'::jsonb, '2'::jsonb, 'ภูมิคุ้มกันทางคุณธรรมคือความพร้อมในการเผชิญสิ่งล่อใจและแรงกดดัน โดยไม่หวั่นไหวไปทำความชั่ว', 'medium', '[หน่วยที่ 3] ภูมิคุ้มกันในตัวที่ดี'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การศึกษาเรียนรู้เกี่ยวกับ "สิทธิและหน้าที่ตามรัฐธรรมนูญและกฎหมายต่อต้านการทุจริต" จัดเป็นองค์ประกอบใดในโมเดล STRONG', '["S (Sufficient)","T (Transparent)","G (Generosity)","N (Knowledge)"]'::jsonb, '3'::jsonb, 'N = Knowledge คือการเสริมสร้างความรู้ทางกฎหมาย สิทธิ หน้าที่ และคุณธรรม', 'medium', '[หน่วยที่ 3] โมเดล STRONG - Knowledge (ความรู้)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดคือการแสดง "ความมีน้ำใจ (Generosity)" ที่ถูกต้องและไม่ผิดหลักจริยธรรม', '["แบ่งปันอาหารกลางวันหรือช่วยติวหนังสืออธิบายเนื้อหาให้เพื่อนเข้าใจ","ให้เพื่อนลอกข้อสอบเพราะสงสารเพื่อนกลัวสอบตก","เซ็นชื่อเข้าแถวแทนเพื่อนที่ตื่นสาย","แอบหยิบสมุดเฉลยของครูมาแจกเพื่อน"]'::jsonb, '0'::jsonb, 'ความมีน้ำใจต้องไม่ละเมิดกฎเกณฑ์หรือสนับสนุนการกระทำผิด การช่วยติวหนังสือคือความเอื้ออาทรที่แท้จริง', 'medium', '[หน่วยที่ 3] ความเอื้ออาทรที่ไม่ปนการทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในการนับคะแนนเลือกตั้งประธานนักเรียน ขั้นตอนใดที่แสดงถึง "ความโปร่งใส (Transparent)" สูงสุด', '["นำหีบบัตรไปนับในห้องพักครูแบบปิดประตูล็อก","เปิดหีบบัตรและขานคะแนนพร้อมขีดแต้มบนกระดานต่อหน้าผู้สมัครและผู้มาสังเกตการณ์ทุกคน","ให้ครูประจำชั้นเป็นคนประกาศผลทันทีโดยไม่ต้องเปิดบัตร","นับคะแนนเฉพาะบัตรที่กาเบอร์ที่ตนเองชอบ"]'::jsonb, '1'::jsonb, 'การนับคะแนนอย่างเปิดเผยต่อสายตาสาธารณชนเป็นมาตรฐานของกระบวนการที่โปร่งใสและตรวจสอบได้', 'medium', '[หน่วยที่ 3] ความโปร่งใสในกิจกรรมนักเรียน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การรับประทานอาหารกลางวันที่โรงเรียนจัดให้อย่างหมดจด ไม่เหลือทิ้ง สะท้อนหลักการใด', '["การกินจุเกินความจำเป็น","การกลัวถูกคุณครูทำโทษเพียงอย่างเดียว","การรู้คุณค่าของอาหารและทรัพยากรตามหลักความพอเพียง","การประหยัดพลังงานไฟฟ้า"]'::jsonb, '2'::jsonb, 'การตักอาหารแต่พอดีและรับประทานหมดแสดงถึงความพอประมาณและการเห็นคุณค่าของทรัพยากร', 'medium', '[หน่วยที่ 3] ความพอเพียงกับการบริโภค'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากชุมชนมีการทุจริตสร้างสะพานข้ามคลองจนสะพานพังเสียหาย ชาวบ้านจะได้รับผลกระทบอย่างไร', '["ไม่มีผลกระทบเพราะทุกคนมีเรือพาย","คลองสะอาดขึ้นเพราะไม่มีสะพานบังแดด","ได้ออกกำลังกายว่ายน้ำข้ามคลองแทน","เดินทางสัญจรลำบาก อาจเกิดอุบัติเหตุ และสูญเสียโอกาสทางเศรษฐกิจ"]'::jsonb, '3'::jsonb, 'ผลลัพธ์ของการโกงโครงสร้างพื้นฐานส่งผลกระทบโดยตรงต่อความปลอดภัยและความสะดวกในชีวิตประจำวันของประชาชน', 'medium', '[หน่วยที่ 3] การตระหนักรู้ภัยทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'จิตพอเพียงต้านทุจริต (STRONG Mind) มีส่วนช่วยในการพัฒนาประเทศอย่างไร', '["ช่วยให้คนในชาติมีความซื่อสัตย์ ลดการรั่วไหลของงบประมาณ และพัฒนาชาติได้อย่างยั่งยืน","ช่วยให้ทุกคนมีรถยนต์ขับเท่ากันทุกคน","ช่วยลดการสร้างโรงเรียนและโรงพยาบาล","ช่วยให้ทุกคนไม่ต้องทำงานหนัก"]'::jsonb, '0'::jsonb, 'จิตพอเพียงต้านทุจริตช่วยสร้างวัฒนธรรมสุจริต ทำให้ทรัพยากรของชาติถูกนำไปใช้อย่างคุ้มค่าและเกิดประโยชน์สูงสุด', 'medium', '[หน่วยที่ 3] โมเดล STRONG - จิตพอเพียงต้านทุจริต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'นักเรียนคนใดต่อไปนี้ปฏิบัติตามหลัก "มีเหตุผล" ในปรัชญาเศรษฐกิจพอเพียง', '["แก้วซื้อดินสอใหม่เพราะเห็นเพื่อนมีลายการ์ตูนใหม่ล่าสุด","ก้องใช้ดินสอแท่งเดิมจนสั้นแล้วต่อปลอกปากกาเพื่อใช้ต่อจนหมดแท่ง","กิ่งทิ้งไม้บรรทัดเก่าเพราะอยากได้สีชมพู","เก่งซื้อยางลบ 10 ก้อนพร้อมกันเพื่อเอาของแถม"]'::jsonb, '1'::jsonb, 'การใช้อุปกรณ์อย่างคุ้มค่าจนหมดอายุการใช้งานแสดงถึงความมีเหตุผลและความประหยัด', 'medium', '[หน่วยที่ 3] การสร้างภูมิคุ้มกันทางสังคม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เหตุใดโรงเรียนจึงควรติดป้ายประกาศรายละเอียดโครงการปรับปรุงอาคารเรียนและงบประมาณที่ใช้ไว้ในที่เปิดเผย', '["เพื่อความสวยงามของอาคาร","เพื่อโฆษณาบริษัทรับเหมาก่อสร้าง","เพื่อแสดงความโปร่งใส ให้ครู นักเรียน และผู้ปกครองสามารถร่วมตรวจสอบได้","เพื่อบังแดดให้ระเบียงทางเดิน"]'::jsonb, '2'::jsonb, 'การเปิดเผยข้อมูลสาธารณะ (Open Data) ช่วยสร้างความโปร่งใสและเปิดโอกาสให้ชุมชนร่วมตรวจสอบ', 'medium', '[หน่วยที่ 3] ความโปร่งใสในข้อมูลข่าวสาร'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การที่นักเรียนยอมรับว่าตนเองทำข้อสอบไม่ได้และตั้งใจอ่านหนังสือใหม่ ดีกว่าการพยายามแอบดูข้อสอบเพื่อน สะท้อนหลักการใด', '["ความเกียจคร้าน","ความไม่สนใจผลการเรียน","ความท้อแท้สิ้นหวัง","ความซื่อสัตย์ ความพอเพียงในความสามารถจริง และความมุ่งมั่นพัฒนา (Onward)"]'::jsonb, '3'::jsonb, 'การยอมรับความจริงและมุ่งมั่นพัฒนาตนเองไปข้างหน้าด้วยวิถีทางที่สุจริตคือแก่นแท้ของ Onward', 'medium', '[หน่วยที่ 3] โมเดล STRONG ในมิติต่างๆ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นการพัฒนาตนเองตามหลัก "Onward" ที่ดีที่สุดของนักเรียนชั้น ป.4', '["ตั้งเป้าหมายฝึกฝนทักษะการอ่านเขียนภาษาไทยและคณิตศาสตร์ให้ดีขึ้นทุกวันด้วยความพยายามของตนเอง","จ้างเพื่อนทำการบ้านให้ทุกวันเพื่อจะได้มีผลงานส่ง","รอให้ครูคอยบังคับจึงจะยอมอ่านหนังสือ","หยุดพัฒนาตนเองเพราะคิดว่าเก่งพอแล้ว"]'::jsonb, '0'::jsonb, 'การพัฒนาตนเองอย่างต่อเนื่องด้วยตนเองโดยไม่พึ่งพาการทุจริตเป็นการขับเคลื่อนชีวิตไปสู่ความสำเร็จที่แท้จริง', 'medium', '[หน่วยที่ 3] การพัฒนาตนเองอย่างต่อเนื่อง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'กิจกรรมใดต่อไปนี้สะท้อนคำว่า "Generosity (เอื้ออาทร)" ในบริบทของโรงเรียน', '["การเก็บค่าจ้างช่วยเพื่อนถือกระเป๋า","การร่วมเป็นอาสาสมัครช่วยดูแลน้องอนุบาลข้ามถนนหน้าโรงเรียน","การแอบเอาขนมของน้องมารับประทาน","การยืนดูเพื่อนยกโต๊ะหนักๆ โดยไม่ช่วย"]'::jsonb, '1'::jsonb, 'จิตอาสาในการช่วยเหลือน้องและผู้ที่อ่อนแอกว่าโดยไม่หวังสิ่งตอบแทนคือจิตใจที่เอื้ออาทร', 'medium', '[หน่วยที่ 3] ความเอื้ออาทรและจิตอาสา'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นความเข้าใจที่ "ถูกต้อง" เกี่ยวกับความพอเพียง', '["ความพอเพียงคือการอดอยาก ไม่ซื้ออะไรเลย","ความพอเพียงใช้ได้เฉพาะกับชาวนาชาวสวนเท่านั้น","ความพอเพียงคือการอยู่อย่างสมเหตุสมผลตามฐานะ รู้จักประมาณตน และไม่เบียดเบียนผู้อื่น","ความพอเพียงคือการห้ามใช้เทคโนโลยีสมัยใหม่"]'::jsonb, '2'::jsonb, 'เศรษฐกิจพอเพียงเป็นปรัชญาที่ทุกคนในทุกสาขาอาชีพสามารถนำไปปรับใช้ได้ โดยยึดทางสายกลางและความพอประมาณ', 'medium', '[หน่วยที่ 3] ความพอเพียงในการดำเนินชีวิต'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อมีผู้ส่งข้อความมาทางโทรศัพท์ว่า "คุณคือผู้โชคดีได้รับเงินรางวัล 100,000 บาท กรุณาโอนเงินค่าธรรมเนียม 500 บาทมาก่อน" นักเรียนควรปฏิบัติอย่างไรตามหลัก STRONG (Realise + Knowledge)', '["รีบแอบเอาเงินแม่ไปโอนทันทีเพราะอยากได้รางวัล","โทรศัพท์ไปด่าทอด้วยคำหยาบคาย","ส่งต่อข้อความให้เพื่อนสนิททุกคนในห้อง","รู้เท่าทันกลโกงของมิจฉาชีพ ไม่โอนเงิน และแจ้งผู้ปกครองให้ทราบทันที"]'::jsonb, '3'::jsonb, 'การมีความรู้และความตระหนักรู้ช่วยป้องกันไม่ให้ตกเป็นเหยื่อของมิจฉาชีพที่ใช้ความโลภมาล่อลวง', 'medium', '[หน่วยที่ 3] การรู้เท่าทันความโลภ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ความสัมพันธ์ระหว่าง "ความพอเพียง (Sufficient)" กับ "ความโปร่งใส (Transparent)" มีผลส่งเสริมซึ่งกันและกันอย่างไรในการป้องกันการทุจริต', '["เมื่อคนมีความพอเพียง ไม่โลภ ก็จะไม่มีแรงผลักดันให้ปกปิดหรือคดโกง ส่งผลให้การปฏิบัติงานเปิดเผยและโปร่งใสตรวจสอบได้ง่าย","ไม่มีความสัมพันธ์กันเลยเพราะเป็นคนละตัวอักษร","ความโปร่งใสทำให้คนประหยัดเงินได้มากขึ้น","ความพอเพียงบังคับให้คนต้องทำบัญชีทุกวัน"]'::jsonb, '0'::jsonb, 'ความพอเพียงช่วยลดแรงจูงใจในการทุจริต ส่วนความโปร่งใสช่วยเป็นกลไกควบคุมและตรวจสอบ ทั้งสองส่วนจึงเสริมสร้างสังคมสุจริตอย่างมั่นคง', 'hard', '[หน่วยที่ 3] การสังเคราะห์โมเดล STRONG'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ตามแนวคิด 3 ห่วง 2 เงื่อนไขของปรัชญาเศรษฐกิจพอเพียง "เงื่อนไขคุณธรรม" มีบทบาทสำคัญที่สุดอย่างไรในการต้านทุจริต', '["เป็นตัวกำหนดราคาสินค้าในตลาด","เป็นเข็มทิศกำกับให้การใช้ความรู้และการตัดสินใจเป็นไปอย่างซื่อสัตย์สุจริต ไม่เอารัดเอาเปรียบสังคม","เป็นเงื่อนไขที่ใช้เฉพาะเวลาสอบวิชาพระพุทธศาสนา","เป็นข้อบังคับในการเปิดบัญชีธนาคาร"]'::jsonb, '1'::jsonb, 'หากมีความรู้แต่ขาดคุณธรรม ความรู้นั้นอาจถูกนำไปใช้ในการคดโกง เงื่อนไขคุณธรรมจึงเป็นหัวใจสำคัญ', 'hard', '[หน่วยที่ 3] การวิเคราะห์ปรัชญาเศรษฐกิจพอเพียง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากผู้นำชุมชนนำโมเดล STRONG มาใช้ในการบริหารโครงการพัฒนาหมู่บ้าน สิ่งที่จะเกิดขึ้นในชุมชนคือข้อใด', '["ชาวบ้านเกิดความขัดแย้งและแย่งชิงงบประมาณกัน","หมู่บ้านถูกตัดขาดจากสังคมภายนอก","โครงการมีความคุ้มค่า ประชาชนมีส่วนร่วมรับรู้ ตรวจสอบงบประมาณได้ และเกิดความไว้เนื้อเชื่อใจกันในชุมชน","ผู้นำชุมชนสามารถตัดสินใจทุกอย่างคนเดียวได้เร็วขึ้น"]'::jsonb, '2'::jsonb, 'การบริหารที่โปร่งใสและยึดประโยชน์ของชุมชนจะสร้างความร่วมมือและความไว้วางใจ นำไปสู่การพัฒนาที่ยั่งยืน', 'hard', '[หน่วยที่ 3] โมเดล STRONG ในบริบทชุมชน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การนำ "Generosity (ความเอื้ออาทร)" มาผสมผสานกับการต่อต้านการทุจริต มีจุดประสงค์เพื่อป้องกันสิ่งใดในสังคม', '["ป้องกันไม่ให้คนรวยบริจาคเงิน","เพื่อยกเลิกกฎระเบียบทั้งหมด","ป้องกันไม่ให้มีการเก็บภาษี","ป้องกันสังคมแบบ \"ตัวใครตัวมัน\" และสร้างจิตสาธารณะที่มองเห็นว่าประโยชน์ของส่วนรวมก็คือประโยชน์ของพวกเราทุกคน"]'::jsonb, '3'::jsonb, 'ความเอื้ออาทรช่วยเปลี่ยนกระบวนทัศน์จากการเห็นแก่ประโยชน์ส่วนตัว มาเป็นการเห็นแก่ประโยชน์สุขร่วมกันของสังคม', 'hard', '[หน่วยที่ 3] การแก้ปัญหาเชิงโครงสร้างด้วย STRONG'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เด็กหญิงมายด์อยากได้กระเป๋านักเรียนใบใหม่ราคา 1,500 บาทตามเพื่อน ทั้งที่ใบเก่ายังสภาพดีและแม่มีรายได้น้อย หากมายด์นำหลัก "พอประมาณ" และ "มีเหตุผล" มาพิจารณา มายด์ควรตัดสินใจอย่างไร', '["ใช้กระเป๋าใบเดิมต่อไปอย่างทะนุถนอม และไม่สร้างภาระหนี้สินให้ครอบครัวเกินความจำเป็น","อดข้าวกลางวันทุกวันเพื่อเก็บเงินซื้อกระเป๋าให้ได้เร็วที่สุด","แอบขโมยเงินแม่ไปซื้อเพื่อให้ได้กระเป๋าเหมือนเพื่อน","โกรธแม่ที่ไม่ยอมซื้อให้"]'::jsonb, '0'::jsonb, 'การประมาณตน รู้คุณค่าของสิ่งของ และคำนึงถึงภาระของครอบครัว สะท้อนถึงการมีจิตพอเพียงอย่างแท้จริง', 'hard', '[หน่วยที่ 3] การประเมินสถานการณ์การเงิน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การที่ประชาชนและนักเรียนใช้สิทธิขอดูข้อมูลการใช้งบประมาณของหน่วยงานรัฐตาม พ.ร.บ. ข้อมูลข่าวสารฯ สอดคล้องกับตัวอักษรใดใน STRONG มากที่สุด', '["S (Sufficient)","T (Transparent) และ N (Knowledge)","G (Generosity)","O (Onward) เพียงตัวเดียว"]'::jsonb, '1'::jsonb, 'การใช้สิทธิขอดูข้อมูลสะท้อนความโปร่งใส (Transparent) ที่ประชาชนตรวจสอบได้ โดยต้องอาศัยความรู้ (Knowledge) ทางกฎหมาย', 'hard', '[หน่วยที่ 3] การตรวจสอบภาคประชาชน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เหตุใดการปลูกฝังโมเดล STRONG ตั้งแต่วัยเด็กจึงมีประสิทธิภาพมากกว่าการรอลงโทษผู้ใหญ่ที่กระทำทุจริต', '["เพราะเด็กจดจำคำศัพท์ภาษาอังกฤษได้เร็วกว่า","เพราะเด็กไม่มีโอกาสได้ใช้เงินจำนวนมาก","เพราะเป็นการสร้างภูมิคุ้มกันและปลูกฝังอุปนิสัยสุจริตให้เป็นวิถีชีวิตตั้งแต่ต้น ดีกว่าการตามแก้ปัญหาที่ปลายเหตุ","เพราะผู้ใหญ่ไม่สามารถรับการอบรมได้"]'::jsonb, '2'::jsonb, 'การป้องกันที่ต้นเหตุโดยการปลูกฝังคุณธรรมในจิตสำนึกของเด็ก จะสร้างผู้ใหญ่ที่มีคุณภาพและไม่คิดทุจริตในอนาคต', 'hard', '[หน่วยที่ 3] การขับเคลื่อนสังคมสุจริตอย่างยั่งยืน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดคือหน้าที่สำคัญที่สุดของนักเรียนในฐานะพลเมืองที่ดีในวัยเรียน', '["การไปชุมนุมประท้วง","การเล่นเกมให้ชนะทุกคน","การหาเงินให้ได้มากๆ","การตั้งใจศึกษาเล่าเรียน ปฏิบัติตามกฎของโรงเรียน และช่วยเหลืองานส่วนรวม"]'::jsonb, '3'::jsonb, 'หน้าที่หลักของนักเรียนคือการศึกษาหาความรู้ ฝึกฝนวินัย และปฏิบัติตามกฎระเบียบของโรงเรียนและสังคม', 'easy', '[หน่วยที่ 4] หน้าที่ของพลเมืองที่ดี'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การเดินข้ามถนนอย่างปลอดภัยและถูกกฎระเบียบควรปฏิบัติอย่างไร', '["ข้ามทางม้าลายหรือใช้สะพานลอยคนข้าม","วิ่งตัดหน้ารถยนต์อย่างรวดเร็ว","ก้มหน้าเล่นโทรศัพท์ขณะเดินข้ามถนน","ข้ามตรงบริเวณทางโค้ง"]'::jsonb, '0'::jsonb, 'การข้ามทางม้าลายหรือสะพานลอยช่วยให้ปลอดภัยและเคารพกฎจราจรส่วนรวม', 'easy', '[หน่วยที่ 4] การเคารพกฎจราจร'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อรับประทานไอศกรีมหมดแล้ว ควรทำอย่างไรกับไม้ไอศกรีมและซองพลาสติก', '["โยนลงบนพื้นหญ้าข้างทาง","นำไปทิ้งลงในถังขยะให้ถูกต้อง","ยัดใส่ซอกกระเป๋าเพื่อน","โยนลงท่อระบายน้ำ"]'::jsonb, '1'::jsonb, 'การทิ้งขยะลงถังเป็นความรับผิดชอบพื้นฐานของพลเมืองในการรักษาความสะอาดและสิ่งแวดล้อมส่วนรวม', 'easy', '[หน่วยที่ 4] การรักษาความสะอาดส่วนรวม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การใช้ "เสรีภาพในการพูดหรือแสดงความคิดเห็น" ที่ถูกต้อง คือข้อใด', '["พูดจาด่าทอและใส่ร้ายเพื่อนสนิท","พูดโกหกเพื่อให้ตนเองดูดี","แสดงความคิดเห็นด้วยความสุภาพ มีเหตุผล และไม่ละเมิดสิทธิของผู้อื่น","ตะโกนส่งเสียงดังในโรงพยาบาล"]'::jsonb, '2'::jsonb, 'เสรีภาพในการพูดต้องมาพร้อมความรับผิดชอบ ไม่ละเมิดสิทธิ์ หรือสร้างความเดือดร้อนเสียหายให้ผู้อื่น', 'easy', '[หน่วยที่ 4] สิทธิและเสรีภาพ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การแต่งกายด้วยชุดนักเรียนที่สะอาดเรียบร้อยตามระเบียบของโรงเรียน แสดงถึงสิ่งใด', '["การไม่มีอิสระในการใช้ชีวิต","ความร่ำรวยของครอบครัว","ความล้าหลังไม่ทันสมัย","ความมีวินัยในตนเองและการเคารพกฎกติกาของสถานศึกษา"]'::jsonb, '3'::jsonb, 'การแต่งกายตามระเบียบเป็นการฝึกฝนวินัยและการเคารพข้อตกลงร่วมกันของสังคมโรงเรียน', 'easy', '[หน่วยที่ 4] กฎระเบียบของโรงเรียน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การมาโรงเรียนให้ทันเวลาเข้าแถวเคารพธงชาติ สะท้อนถึงคุณธรรมข้อใด', '["ความตรงต่อเวลาและการมีวินัยในตนเอง","ความประหยัด","ความเกรงใจเพื่อน","ความรักชาติเฉพาะตอนเช้า"]'::jsonb, '0'::jsonb, 'การตรงต่อเวลาเป็นพื้นฐานสำคัญของวินัยและความรับผิดชอบต่อหน้าที่', 'easy', '[หน่วยที่ 4] การตรงต่อเวลา'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อคุณครูสั่งการบ้าน สิ่งที่นักเรียนควรปฏิบัติคือข้อใด', '["รอมาลอกเพื่อนในตอนเช้าก่อนเข้าแถว","ทำด้วยตนเองให้เสร็จเรียบร้อยและส่งตามกำหนดเวลา","แกล้งบอกครูว่าลืมสมุดไว้ที่บ้าน","จ้างพี่ชายทำให้"]'::jsonb, '1'::jsonb, 'การทำการบ้านด้วยตนเองเป็นการฝึกความรับผิดชอบต่อหน้าที่และทบทวนความรู้', 'easy', '[หน่วยที่ 4] ความรับผิดชอบต่อตนเอง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นการกระทำที่แสดงถึง "จิตสาธารณะ" ในโรงเรียน', '["เตะขยะไปไว้หน้าห้องเรียนอื่น","นั่งดูขยะปลิวไปมาโดยไม่สนใจ","ช่วยเก็บขยะที่ตกอยู่บริเวณลานกีฬา แม้จะไม่ใช่เวรของตนเอง","รอให้ครูสั่งจึงค่อยยอมเก็บขยะ"]'::jsonb, '2'::jsonb, 'จิตสาธารณะคือการลงมือทำประโยชน์เพื่อส่วนรวมด้วยความเต็มใจโดยไม่ต้องมีใครสั่งหรือหวังสิ่งตอบแทน', 'easy', '[หน่วยที่ 4] จิตสาธารณะ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การส่งเสียงดังโหวกเหวกในห้องสมุด ถือเป็นการกระทำที่ถูกต้องหรือไม่ เพราะเหตุใด', '["ถูกต้อง หากเรากำลังคุยเรื่องเรียน","ไม่ถูกต้อง เฉพาะเมื่อมีคนมาเตือนเท่านั้น","ถูกต้อง หากไม่มีคุณครูบรรณารักษ์อยู่","ไม่ถูกต้อง เพราะเป็นการรบกวนสมาธิและละเมิดสิทธิในการอ่านหนังสือของผู้อื่น"]'::jsonb, '3'::jsonb, 'ห้องสมุดต้องการความเงียบสงบ การส่งเสียงดังเป็นการละเมิดสิทธิของผู้ใช้บริการคนอื่น', 'easy', '[หน่วยที่ 4] การเคารพสิทธิผู้อื่น'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อนักเรียนไอหรือจามในที่สาธารณะ ควรปฏิบัติตนอย่างไรเพื่อความรับผิดชอบต่อส่วนรวม', '["ใช้กระดาษทิชชูหรือข้อศอกด้านในปิดปากและจมูก หรือสวมหน้ากากอนามัย","หันหน้าไปจามใส่เพื่อนข้างๆ","จามเสียงดังๆ เพื่อระบายอากาศ","เอามือป้องแล้วเอาไปเช็ดโต๊ะเรียน"]'::jsonb, '0'::jsonb, 'การปิดปากและจมูกเมื่อไอหรือจามช่วยป้องกันการแพร่กระจายของเชื้อโรคสู่ผู้อื่นในสังคม', 'easy', '[หน่วยที่ 4] ความรับผิดชอบต่อสังคม'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การลงคะแนนเสียงเลือกตั้งหัวหน้าห้องเรียน เป็นการฝึกฝนทักษะใด', '["การเป็นนักการเมืองอาชีพ","วิถีชีวิตประชาธิปไตยและการมีส่วนร่วมตัดสินใจตามกติกา","การแข่งขันเพื่อเอาชนะกัน","การหาผลประโยชน์ใส่ตัว"]'::jsonb, '1'::jsonb, 'การเลือกตั้งหัวหน้าห้องเป็นการฝึกฝนการใช้สิทธิและการเคารพเสียงส่วนใหญ่ตามวิถีประชาธิปไตย', 'easy', '[หน่วยที่ 4] การมีส่วนร่วมในระบอบประชาธิปไตย'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'คำว่า "พลเมืองตื่นรู้ (Active Citizen)" มีลักษณะเด่นอย่างไร', '["คนที่ตื่นเช้ามาเล่นเกมทุกวัน","คนที่ชอบวิพากษ์วิจารณ์ผู้อื่นในอินเทอร์เน็ตแต่ไม่เคยลงมือทำอะไร","คนที่ไม่นิ่งดูดายเมื่อเห็นปัญหาในสังคม มีส่วนร่วมในการแก้ปัญหา และร่วมกันสร้างสรรค์ประโยชน์เพื่อส่วนรวม","คนที่คอยทำตามคำสั่งของผู้อื่นตลอดเวลาโดยไม่คิด"]'::jsonb, '2'::jsonb, 'พลเมืองตื่นรู้คือผู้ที่ตระหนักในบทบาทหน้าที่ของตน ลุกขึ้นมามีส่วนร่วมดูแลสังคม และไม่ยอมรับความอยุติธรรม', 'medium', '[หน่วยที่ 4] พลเมืองตื่นรู้ (Active Citizen)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อมีเพื่อนใหม่ย้ายมาจากต่างจังหวัดที่มีสำเนียงการพูดและวัฒนธรรมแตกต่างจากเรา พลเมืองที่ดีควรปฏิบัติต่อเพื่อนอย่างไร', '["ล้อเลียนสำเนียงการพูดของเพื่อนให้เป็นเรื่องตลก","สั่งให้เพื่อนใหม่เปลี่ยนสำเนียงทันที","ชวนเพื่อนคนอื่นไม่ให้พูดคุยกับเพื่อนใหม่","ให้เกียรติ ยอมรับความแตกต่าง เป็นมิตร และช่วยแนะนำเพื่อนให้ปรับตัวเข้ากับโรงเรียน"]'::jsonb, '3'::jsonb, 'การยอมรับและเคารพในความแตกต่างหลากหลาย (Diversity) เป็นหัวใจของสังคมประชาธิปไตยที่สงบสุข', 'medium', '[หน่วยที่ 4] การเคารพความแตกต่างหลากหลาย'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'สิทธิเด็กขั้นพื้นฐานระบุว่า "เด็กทุกคนมีสิทธิที่จะได้รับการศึกษา" ควบคู่ไปกับสิ่งใดที่เด็กต้องปฏิบัติ', '["มีหน้าที่ตั้งใจเล่าเรียนและใช้ความรู้นั้นพัฒนาตนเองและสังคม","มีหน้าที่เรียกร้องของรางวัลจากโรงเรียน","มีหน้าที่ตัดสินใจว่าจะไม่ไปโรงเรียนก็ได้","ไม่มีหน้าที่ใดๆ จนกว่าจะอายุ 20 ปี"]'::jsonb, '0'::jsonb, 'สิทธิมาพร้อมกับหน้าที่เสมอ เมื่อได้รับสิทธิทางการศึกษา ย่อมมีหน้าที่ตั้งใจเรียนและพัฒนาตนเอง', 'medium', '[หน่วยที่ 4] สิทธิเด็กและหน้าที่'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นการแสดงความรับผิดชอบต่อสิ่งแวดล้อมในชุมชนที่ถูกต้องและยั่งยืนที่สุด', '["เผาขยะใบไม้ในสวนหลังบ้านเพื่อความรวดเร็ว","คัดแยกขยะก่อนทิ้ง ลดการใช้ถุงพลาสติกครั้งเดียวทิ้ง และร่วมกิจกรรมปลูกต้นไม้ในชุมชน","เทน้ำเสียลงในคูคลองสาธารณะในเวลากลางคืน","ซื้อสินค้าที่มีบรรจุภัณฑ์พลาสติกหลายชั้น"]'::jsonb, '1'::jsonb, 'การคัดแยกขยะและลดการใช้พลาสติกช่วยลดมลพิษและรักษาสิ่งแวดล้อมของชุมชน', 'medium', '[หน่วยที่ 4] การอนุรักษ์สิ่งแวดล้อมของชุมชน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในการประชุมกลุ่มทำโครงงาน เมื่อที่ประชุมลงมติเลือกหัวข้อที่ตนเองไม่ชอบ สมาชิกกลุ่มที่ดีควรปฏิบัติตนอย่างไร', '["ประท้วงโดยการไม่ยอมช่วยทำงานใดๆ เลย","แอบไปบอกครูให้ยกเลิกกลุ่ม","เคารพมติเสียงส่วนใหญ่ของกลุ่ม และพร้อมร่วมมือทำงานที่ได้รับมอบหมายอย่างเต็มความสามารถ","ชวนเพื่อนที่ออกเสียงเหมือนตนเองแยกไปทำกลุ่มใหม่"]'::jsonb, '2'::jsonb, 'หลักการประชาธิปไตยคือการเคารพมติเสียงส่วนใหญ่ ขณะเดียวกันก็ต้องรับฟังและให้เกียรติเสียงส่วนน้อย', 'medium', '[หน่วยที่ 4] การยอมรับมติเสียงส่วนใหญ่'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากพบเห็นก๊อกน้ำในสวนสาธารณะชำรุด มีน้ำไหลรั่วทิ้งตลอดเวลา พลเมืองตื่นรู้ควรทำอย่างไร', '["เดินผ่านไปเพราะไม่ใช่บ้านของเรา","ถ่ายรูปลงโซเชียลมีเดียด่าทอเจ้าหน้าที่","นำสบู่มาอาบน้ำตรงนั้นเพื่อใช้ประโยชน์","ช่วยปิดวาล์วน้ำหากทำได้ และแจ้งเจ้าหน้าที่ดูแลสวนสาธารณะหรือเทศบาลให้เข้ามาซ่อมแซม"]'::jsonb, '3'::jsonb, 'การช่วยป้องกันความเสียหายเบื้องต้นและแจ้งหน่วยงานรับผิดชอบเป็นการกระทำของพลเมืองที่มีจิตสำนึก', 'medium', '[หน่วยที่ 4] ความรับผิดชอบต่อทรัพย์สินสาธารณะ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เหตุใดสังคมจึงต้องมี "กฎหมายและกฎระเบียบ" ในการอยู่ร่วมกัน', '["เพื่อสร้างความสงบเรียบร้อย ความเป็นธรรม และคุ้มครองความปลอดภัยของทุกคนในสังคม","เพื่อลงโทษคนให้ได้รับความเดือดร้อน","เพื่อแสดงอำนาจของผู้ปกครอง","เพื่อให้มีงานให้ตำรวจทำ"]'::jsonb, '0'::jsonb, 'กฎหมายมีไว้เพื่อรักษาความสงบสุข ความเป็นธรรม และปกป้องสิทธิของคนทุกคนในสังคม', 'medium', '[หน่วยที่ 4] การปฏิบัติตามกฎหมายและกฎระเบียบ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อเกิดเหตุการณ์น้ำท่วมในชุมชนใกล้เคียง นักเรียนชั้น ป.4 สามารถแสดงความรับผิดชอบต่อสังคมได้อย่างไรตามวัยของตน', '["ขับเรือยนต์เข้าไปในพื้นที่น้ำท่วมเพื่อถ่ายคลิป","ร่วมบริจาคสิ่งของเครื่องใช้จำเป็น ขนม สมุดดินสอ หรือเขียนจดหมายส่งกำลังใจให้ผู้ประสบภัย","เรียกร้องให้รัฐบาลยกเลิกการสอบ","เฉยเมยเพราะบ้านตนเองน้ำไม่ท่วม"]'::jsonb, '1'::jsonb, 'เด็กสามารถมีส่วนร่วมช่วยเหลือสังคมได้ตามกำลังและวัย เช่น การบริจาคสิ่งของหรือการให้กำลังใจ', 'medium', '[หน่วยที่ 4] จิตอาสาในสถานการณ์ภัยพิบัติ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การเป็นพลเมืองดิจิทัลที่ดี (Good Digital Citizen) ในการใช้อินเทอร์เน็ต คือข้อใด', '["การแอบแคปหน้าจอแชตส่วนตัวของเพื่อนไปนินทาในกลุ่มอื่น","การใช้บัญชีปลอมเข้าไปด่าทอผู้อื่น","การไม่โพสต์ข้อความกลั่นแกล้งผู้อื่น (Cyberbullying) ไม่ส่งต่อข่าวปลอม และให้เกียรติผู้อื่นในโลกออนไลน์","การแอบขโมยรหัสผ่านเฟซบุ๊กของเพื่อน"]'::jsonb, '2'::jsonb, 'พลเมืองดิจิทัลที่ดีต้องมีจริยธรรม ไม่กลั่นแกล้งใคร ตรวจสอบความถูกต้องของข้อมูลก่อนแชร์ และเคารพสิทธิส่วนบุคคล', 'medium', '[หน่วยที่ 4] มารยาทในโลกไซเบอร์ (Digital Citizenship)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ข้อใดเป็นการประหยัดพลังงานเพื่อส่วนรวมที่สามารถทำได้จริงในชีวิตประจำวัน', '["เปิดแอร์อุณหภูมิ 16 องศาเซลเซียสแล้วห่มผ้านวมหนาๆ","ใช้ลิฟต์ขึ้นลงเพียงแค่ 1 ชั้นเป็นประจำ","เปิดโทรทัศน์ทิ้งไว้เป็นเพื่อนตอนนอนหลับ","ปิดสวิตช์ไฟและถอดปลั๊กเครื่องใช้ไฟฟ้าทุกครั้งเมื่อไม่ใช้งาน"]'::jsonb, '3'::jsonb, 'การถอดปลั๊กและปิดไฟเมื่อเลิกใช้ช่วยลดการใช้เชื้อเพลิงผลิตไฟฟ้าและลดภาวะโลกร้อน', 'medium', '[หน่วยที่ 4] ความรับผิดชอบต่อการใช้พลังงาน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การเข้าร่วมกิจกรรมวันสำคัญทางศาสนา วันชาติ หรือวันสิ่งแวดล้อมของโรงเรียน มีประโยชน์อย่างไร', '["ช่วยปลูกฝังความรัก ความสามัคคี ความกตัญญู และการสืบทอดวัฒนธรรมอันดีงามของชาติ","ช่วยให้ได้หยุดเรียนครึ่งวัน","ทำให้ได้กินขนมฟรี","ไม่มีประโยชน์อะไรนอกจากความเหน็ดเหนื่อย"]'::jsonb, '0'::jsonb, 'กิจกรรมวันสำคัญช่วยเสริมสร้างจิตสำนึก ความภาคภูมิใจในวัฒนธรรม และความสามัคคีในชุมชน', 'medium', '[หน่วยที่ 4] การมีส่วนร่วมในกิจกรรมโรงเรียน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อมีการเข้าแถวรอขึ้นรถรับส่งนักเรียน หากมีรุ่นพี่เดินมาแซงคิวน้องๆ นักเรียนควรปฏิบัติอย่างไรอย่างเหมาะสม', '["ยืนเงียบๆ และก้มหน้ายอมรับ","บอกเตือนรุ่นพี่ด้วยความสุภาพว่า \"กรุณาต่อแถวตามลำดับด้วยครับ เพื่อความเป็นระเบียบและปลอดภัย\"","ใช้ก้อนหินปาใส่รุ่นพี่","ผลักน้องข้างหน้าให้ล้ม"]'::jsonb, '1'::jsonb, 'การตักเตือนด้วยความสุภาพแต่หนักแน่นช่วยสร้างบรรทัดฐานที่ดีในโรงเรียนโดยไม่ใช้ความรุนแรง', 'medium', '[หน่วยที่ 4] ความกล้าหาญในการปกป้องกติกา'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อได้รับข้อความทางไลน์ที่บอกว่า "ห้ามกินน้ำอัดลมกับกล้วยหอมเด็ดขาด จะกลายเป็นยาพิษถึงตาย แชร์ด่วน!" ควรทำอย่างไรเป็นอันดับแรก', '["รีบกดแชร์ส่งต่อให้ทุกคนที่รู้จักทันทีด้วยความหวังดี","รีบไปบอกให้แม่โยนกล้วยหอมทิ้งทั้งหมด","ตรวจสอบความถูกต้องของข้อมูลจากแหล่งข่าวที่เชื่อถือได้ (เช่น หมอจริง แพทย์แผนปัจจุบัน หรือหน่วยงานทางการ) ก่อนเชื่อหรือแชร์","พิมพ์ด่าคนที่ส่งมาหาเราทันที"]'::jsonb, '2'::jsonb, 'พลเมืองที่มีความรับผิดชอบต้องคิดวิเคราะห์และตรวจสอบข้อเท็จจริง (Fact-check) ก่อนส่งต่อข้อมูล', 'medium', '[หน่วยที่ 4] พลเมืองกับการต่อต้านข่าวปลอม (Fake News)'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อไปทัศนศึกษาที่วัดหรือพิพิธภัณฑ์ประวัติศาสตร์ พฤติกรรมใดที่ไม่ควรทำอย่างเด็ดขาด', '["เดินชมอย่างเป็นระเบียบและอ่านป้ายคำบรรยาย","แต่งกายสุภาพเรียบร้อยเหมาะสมกับสถานที่","ปฏิบัติตามคำแนะนำของวิทยากรประจำพิพิธภัณฑ์","ใช้ปากกาหรือหินขีดเขียนชื่อตนเองลงบนกำแพงวัดหรือโบราณสถานเพื่อเป็นที่ระลึก"]'::jsonb, '3'::jsonb, 'การขีดเขียนโบราณสถานเป็นการทำลายมรดกทางวัฒนธรรมของชาติและเป็นการกระทำที่ผิดกฎหมาย', 'medium', '[หน่วยที่ 4] การดูแลรักษาโบราณสถานและแหล่งเรียนรู้'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในการประเมินความพึงพอใจการจัดกิจกรรมของโรงเรียน การตอบแบบสอบถามควรยึดหลักใด', '["ตอบตามความรู้สึกและข้อเท็จจริงอย่างตรงไปตรงมาและสร้างสรรค์ เพื่อให้โรงเรียนนำไปปรับปรุงจริง","เขียนชมทุกข้อตามที่เพื่อนบอกเพื่อเอาใจครู","เขียนคำหยาบคายลงในช่องข้อเสนอแนะ","กาเครื่องหมายมั่วๆ ให้เสร็จเร็วที่สุด"]'::jsonb, '0'::jsonb, 'การสะท้อนข้อมูลที่เป็นจริงและสร้างสรรค์เป็นเครื่องมือสำคัญในการพัฒนาคุณภาพการศึกษา', 'medium', '[หน่วยที่ 4] ความซื่อสัตย์ในการแสดงความคิดเห็น'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การไม่นำปมด้อย รูปร่าง หน้าตา หรือฐานะความยากจนของเพื่อนมาล้อเลียน เป็นการปฏิบัติตามหลักการใด', '["การแกล้งทำเป็นคนดี","การเคารพในศักดิ์ศรีความเป็นมนุษย์และความเสมอภาค","ความกลัวว่าจะถูกเพื่อนชกต่อย","การไม่มีอารมณ์ขัน"]'::jsonb, '1'::jsonb, 'มนุษย์ทุกคนมีศักดิ์ศรีเท่าเทียมกัน การให้เกียรติผู้อื่นและไม่เหยียดหยามเป็นรากฐานของสิทธิมนุษยชน', 'medium', '[หน่วยที่ 4] สิทธิมนุษยชนเบื้องต้น'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'การเข้าร่วมโครงการ "หน้าบ้าน น่ามอง" ช่วยทำความสะอาดทางเดินสาธารณะหน้าบ้านตนเอง ส่งผลดีอย่างไรต่อชุมชน', '["ทำให้เพื่อนบ้านอิจฉา","ทำให้ต้องเสียค่าน้ำล้างถนนมากขึ้น","ทำให้ชุมชนสะอาด สวยงาม ปลอดภัยจากสัตว์มีพิษ และน่าอยู่อาศัย","ไม่มีประโยชน์ต่อใครเลย"]'::jsonb, '2'::jsonb, 'การเริ่มต้นดูแลพื้นที่หน้าบ้านตนเองเชื่อมโยงไปสู่ความสะอาดเรียบร้อยและความน่าอยู่ของชุมชนส่วนรวม', 'medium', '[หน่วยที่ 4] การมีส่วนร่วมในชุมชน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เหตุใดระบอบประชาธิปไตยจึงไม่ได้หมายถึงเพียงแค่ "การไปกากบาทเลือกตั้งทุก 4 ปี" แต่รวมถึงวิถีชีวิตประจำวันด้วย', '["เพราะการเลือกตั้งจัดขึ้นบ่อยเกินไป","เพราะคนส่วนใหญ่ไม่ชอบไปเลือกตั้ง","เพราะรัฐบาลต้องการประหยัดงบประมาณการเลือกตั้ง","เพราะประชาธิปไตยคือการเคารพสิทธิผู้อื่น การรับฟังความคิดเห็นที่แตกต่าง การปฏิบัติตามกฎหมาย และความรับผิดชอบต่อส่วนรวมในทุกๆ วัน"]'::jsonb, '3'::jsonb, 'วิถีประชาธิปไตย (Democratic Culture) คือการใช้ชีวิตที่ยึดมั่นในความเสมอภาค เคารพสิทธิ เสรีภาพ และภราดรภาพในทุกมิติ', 'hard', '[หน่วยที่ 4] การวิเคราะห์บทบาทพลเมืองประชาธิปไตย'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'หากการทิ้งขยะลงในแม่น้ำลำคลองสะดวกสบายและไม่มีกล้องวงจรปิดจับภาพได้ แต่เราเลือกที่จะเก็บขยะไว้ในกระเป๋าเพื่อนำไปทิ้งที่บ้าน การกระทำนี้บ่งชี้ถึงพัฒนาการทางจริยธรรมระดับใด', '["ระดับการมีจิตสำนึกรับผิดชอบต่อสิ่งแวดล้อมและสังคมจากหลักการภายในตนเองอย่างแท้จริง","ระดับความต้องการคำชมเชยจากคนรอบข้าง","ระดับกลัวการลงโทษจากผู้อื่น","ระดับความลังเลไม่แน่ใจ"]'::jsonb, '0'::jsonb, 'การทำความดีโดยไม่ขึ้นอยู่กับการมีผู้ตรวจตรา สะท้อนถึงพัฒนาการทางจริยธรรมขั้นสูงที่มีหลักคุณธรรมภายในจิตใจ', 'hard', '[หน่วยที่ 4] การตัดสินใจเชิงจริยธรรมของพลเมือง'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'แนวคิด "คิดระดับโลก ทำระดับท้องถิ่น (Think Globally, Act Locally)" สามารถนำมาประยุกต์ใช้ในการเป็นพลเมืองที่มีความรับผิดชอบได้อย่างไร', '["การเดินทางไปเที่ยวต่างประเทศบ่อยๆ","การตระหนักถึงปัญหาระดับโลก เช่น ภาวะโลกร้อน แล้วเริ่มต้นลงมือแก้ไขจากสิ่งใกล้ตัว เช่น การลดขยะในโรงเรียนและชุมชนของตนเอง","การเลิกใช้ภาษาไทยแล้วพูดภาษาอังกฤษอย่างเดียว","การรอรับเงินช่วยเหลือจากองค์กรระหว่างประเทศ"]'::jsonb, '1'::jsonb, 'การมองเห็นภาพรวมของปัญหาระดับโลกและเริ่มต้นลงมือทำจากจุดเล็กๆ ที่ตนเองทำได้ในชีวิตประจำวัน', 'hard', '[หน่วยที่ 4] การขับเคลื่อนสังคมด้วยพลังเยาวชน'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'ในฐานะพลเมืองตามระบอบประชาธิปไตย การมีส่วนร่วมตรวจสอบการทำงานของข้าราชการและนักการเมือง มีความสำคัญสูงสุดอย่างไร', '["เพื่อให้ข้าราชการทำงานช้าลง","เพื่อหาทางฟ้องร้องเรียกเงินค่าปรับ","เพื่อป้องกันการใช้อำนาจในทางที่ผิด การทุจริตคอร์รัปชัน และทำให้การบริหารราชการแผ่นดินเกิดประโยชน์สูงสุดต่อประชาชน","เพื่อแย่งชิงตำแหน่งหน้าที่การงาน"]'::jsonb, '2'::jsonb, 'อำนาจอธิปไตยเป็นของประชาชน การตรวจสอบถ่วงดุลช่วยให้การใช้อำนาจเป็นไปเพื่อประโยชน์สุขของส่วนรวม', 'hard', '[หน่วยที่ 4] การตรวจสอบอำนาจรัฐ'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เมื่อเกิดความขัดแย้งเรื่องการใช้สนามกีฬาในโรงเรียนระหว่างกลุ่มเพื่อน 2 กลุ่ม แนวทางแก้ปัญหาแบบ "สันติวิธีและประชาธิปไตย" คือข้อใด', '["กลุ่มใดมีคนมากกว่าให้ได้สิทธิ์เล่นตลอดเวลา","การปิดสนามไม่ให้ใครเล่นเลยตลอดทั้งเทอม","การท้าดวลชกต่อย ใครชนะได้ครองสนาม","การจัดตัวแทนมาพูดคุยเจรจาด้วยเหตุผล ทำข้อตกลงแบ่งเวลาการใช้งานอย่างเป็นธรรมและเคารพกติกากัน"]'::jsonb, '3'::jsonb, 'การเจรจาด้วยเหตุผลและการประนีประนอมบนพื้นฐานความเป็นธรรมเป็นหัวใจของการแก้ปัญหาด้วยสันติวิธี', 'hard', '[หน่วยที่ 4] การจัดการความขัดแย้งโดยสันติวิธี'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'คำกล่าวที่ว่า "เสรีภาพของบุคคลหนึ่งสิ้นสุดลง ณ จุดที่เสรีภาพของบุคคลอื่นเริ่มต้นขึ้น" มีความหมายตรงกับข้อใดมากที่สุด', '["เรามีเสรีภาพในการทำสิ่งใดก็ได้ ตราบใดที่ไม่ไปละเมิดสิทธิ เสรีภาพ หรือสร้างความเสียหายให้แก่ผู้อื่น","เราไม่มีเสรีภาพในการทำอะไรเลยในสังคม","คนที่แข็งแรงกว่าย่อมมีเสรีภาพมากกว่าคนอื่น","เสรีภาพเป็นสิ่งที่มีขอบเขตเฉพาะในบ้านตนเองเท่านั้น"]'::jsonb, '0'::jsonb, 'เสรีภาพที่แท้จริงต้องอยู่ภายใต้กรอบของกฎหมายและไม่ก้าวก่ายหรือละเมิดสิทธิของผู้อื่น', 'hard', '[หน่วยที่ 4] ความสมดุลระหว่างสิทธิและหน้าที่'),
  ('ต้านทุจริต', 'ป.4', 'mcq', 'เป้าหมายสูงสุดของการศึกษาเรื่อง "พลเมืองและความรับผิดชอบต่อสังคม" สำหรับนักเรียนคือสิ่งใด', '["เพื่อให้จำข้อสอบไปกาคำตอบได้คะแนนเต็ม","เพื่อบ่มเพาะให้นักเรียนเติบโตเป็นมนุษย์ที่สมบูรณ์ มีจิตสำนึกสาธารณะ ซื่อสัตย์สุจริต และพร้อมร่วมสร้างสรรค์สังคมที่ดีงามอย่างยั่งยืน","เพื่อให้นักเรียนทุกคนเป็นผู้นำชุมชนในอนาคต","เพื่อให้ปฏิบัติตามคำสั่งโดยไม่ต้องตั้งคำถาม"]'::jsonb, '1'::jsonb, 'การศึกษาความเป็นพลเมืองมุ่งหวังสร้างคนดี คนเก่ง และคนที่มีจิตสำนึกสาธารณะ เพื่อเป็นกำลังสำคัญในการพัฒนาประเทศ', 'hard', '[หน่วยที่ 4] จิตสำนึกพลเมืองกับการพัฒนาที่ยั่งยืน');
